def _get_column_indices(X, key):
    """Get feature column indices for input data X and key.

    For accepted values of `key`, see the docstring of
    :func:`_safe_indexing`.
    """
    key_dtype = _determine_key_type(key)
    if nw.dependencies.is_into_dataframe(X):
        df_nw = nw.from_native(X)
        n_columns = df_nw.shape[1]
        column_names = df_nw.columns
    else:
        n_columns = X.shape[1]
        column_names = None
    if isinstance(key, (list, tuple)) and (not key):
        return []
    elif key_dtype in ('bool', 'int'):
        return _get_column_indices_for_bool_or_int(key, n_columns)
    else:
        if column_names is None:
            raise ValueError('Specifying the columns using strings is only supported for dataframes.')
        if isinstance(key, slice):
            if key.step not in [1, None]:
                raise NotImplementedError('key.step must be 1 or None')
            start, stop = (key.start, key.stop)
            if start is not None:
                start = column_names.index(start)
            if stop is not None:
                stop = column_names.index(stop) + 1
            else:
                stop = n_columns + 1
            return list(islice(range(n_columns), start, stop))
        else:
            selected_columns = [key] if np.isscalar(key) else key
            try:
                return [column_names.index(col) for col in selected_columns]
            except ValueError as e:
                missing = {*selected_columns} - {*column_names}
                msg = f'Some column names are not columns of the dataframe: {missing}'
                raise ValueError(msg) from e

def color(value, index, command, comm_arg):
    """
        CSS colors have 5 formats to process:

         - 6 digit hex code: "#ff23ee"     --> [HTML]{FF23EE}
         - 3 digit hex code: "#f0e"        --> [HTML]{FF00EE}
         - rgba: rgba(128, 255, 0, 0.5)    --> [rgb]{0.502, 1.000, 0.000}
         - rgb: rgb(128, 255, 0,)          --> [rbg]{0.502, 1.000, 0.000}
         - string: red                     --> {red}

        Additionally rgb or rgba can be expressed in % which is also parsed.
        """
    arg = index if index != '' else comm_arg
    if value[0] == '#' and len(value) == 7:
        return (command, f'[HTML]{{{value[1:].upper()}}}{arg}')
    if value[0] == '#' and len(value) == 4:
        val = f'{value[1].upper() * 2}{value[2].upper() * 2}{value[3].upper() * 2}'
        return (command, f'[HTML]{{{val}}}{arg}')
    elif value[:3] == 'rgb':
        r = re.findall('(?<=\\()[0-9\\s%]+(?=,)', value)[0].strip()
        r = float(r[:-1]) / 100 if '%' in r else int(r) / 255
        g = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[0].strip()
        g = float(g[:-1]) / 100 if '%' in g else int(g) / 255
        if value[3] == 'a':
            b = re.findall('(?<=,)[0-9\\s%]+(?=,)', value)[1].strip()
        else:
            b = re.findall('(?<=,)[0-9\\s%]+(?=\\))', value)[0].strip()
        b = float(b[:-1]) / 100 if '%' in b else int(b) / 255
        return (command, f'[rgb]{{{r:.3f}, {g:.3f}, {b:.3f}}}{arg}')
    else:
        return (command, f'{{{value}}}{arg}')

def _dt_subday_component(self, component: str, modulo: int) -> Self:
    """
        Extract a sub-day component (hours, minutes, etc.) from the day remainder.

        The remainder is always non-negative, so we can use integer division.
        """
    unit = self._duration_unit
    divisors = _DURATION_DIVISORS[component]
    if unit not in divisors:
        return self._dt_zero_or_null_int32()
    result = pc.divide(self._dt_day_remainder, divisors[unit])
    result = mod_int(result, modulo)
    return self._from_pyarrow_array(result.cast(pa.int32()))

def _wrap_header_guess_version(header):
    """
    Like `_wrap_header`, but chooses an appropriate version given the contents
    """
    try:
        return _wrap_header(header, (1, 0))
    except ValueError:
        pass
    try:
        ret = _wrap_header(header, (2, 0))
    except UnicodeEncodeError:
        pass
    else:
        warnings.warn('Stored array in format 2.0. It can only beread by NumPy >= 1.9', UserWarning, stacklevel=2)
        return ret
    header = _wrap_header(header, (3, 0))
    warnings.warn('Stored array in format 3.0. It can only be read by NumPy >= 1.17', UserWarning, stacklevel=2)
    return header

def _nanquantile_ureduce_func(a: np.ndarray, q: np.ndarray, weights: np.ndarray, axis: int | None=None, out=None, overwrite_input: bool=False, method='linear', weak_q=False):
    """
    Private function that doesn't support extended axis or keepdims.
    These methods are extended to this function using _ureduce
    See nanpercentile for parameter usage
    """
    if axis is None or a.ndim == 1:
        part = a.ravel()
        wgt = None if weights is None else weights.ravel()
        result = _nanquantile_1d(part, q, overwrite_input, method, weights=wgt, weak_q=weak_q)
    elif weights is None:
        result = np.apply_along_axis(_nanquantile_1d, axis, a, q, overwrite_input, method, weights, weak_q)
        if q.ndim != 0:
            from_ax = [axis + i for i in range(q.ndim)]
            result = np.moveaxis(result, from_ax, list(range(q.ndim)))
    else:
        a = np.moveaxis(a, axis, -1)
        if weights is not None:
            weights = np.moveaxis(weights, axis, -1)
        if out is not None:
            result = out
        else:
            result = np.empty_like(a, shape=q.shape + a.shape[:-1])
        for ii in np.ndindex(a.shape[:-1]):
            result[(...,) + ii] = _nanquantile_1d(a[ii], q, weights=weights[ii], overwrite_input=overwrite_input, method=method, weak_q=weak_q)
        return result
    if out is not None:
        out[...] = result
    return result

@staticmethod
def _num_combinations(n_features, min_degree, max_degree, interaction_only, include_bias):
    """Calculate number of terms in polynomial expansion

        This should be equivalent to counting the number of terms returned by
        _combinations(...) but much faster.
        """
    if interaction_only:
        combinations = sum([comb(n_features, i, exact=True) for i in range(max(1, min_degree), min(max_degree, n_features) + 1)])
    else:
        combinations = comb(n_features + max_degree, max_degree, exact=True) - 1
        if min_degree > 0:
            d = min_degree - 1
            combinations -= comb(n_features + d, d, exact=True) - 1
    if include_bias:
        combinations += 1
    return combinations

def replace_regex(record: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """
    if isna(value) or not isinstance(value, str):

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return value if rx.search(s) is not None else s
            else:
                return s
    else:

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return rx.sub(value, s)
            else:
                return s
    f = np.vectorize(re_replacer, otypes=[np.object_])
    if mask is None:
        record[:] = f(record)
    else:
        if record.ndim != mask.ndim:
            mask = np.broadcast_to(mask, record.shape)
        record[mask] = f(record[mask])

