def json(self, **kwargs: Any) -> Any:
    """Decodes the JSON response body (if any) as a Python object.

        This may return a dictionary, list, etc. depending on what is in the response.

        :param \\*\\*kwargs: Optional arguments that ``json.loads`` takes.
        :raises requests.exceptions.JSONDecodeError: If the response body does not
            contain valid json.
        """
    if not self.encoding and self.content and (len(self.content) > 3):
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                pass
            except JSONDecodeError as e:
                raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)
    try:
        return complexjson.loads(self.text, **kwargs)
    except JSONDecodeError as e:
        raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

def _maybe_wrap_formatter(formatter: BaseFormatter | None=None, na_rep: str | None=None, precision: int | None=None, field: str='.', thousands: str | None=None, escape: str | None=None, hyperlinks: str | None=None) -> Callable:
    """
    Allows formatters to be expressed as str, callable or None, where None returns
    a default formatting function. wraps with na_rep, and precision where they are
    available.
    """
    if isinstance(formatter, str):
        func_0 = lambda x: formatter.format(x)
    elif callable(formatter):
        func_0 = formatter
    elif formatter is None:
        precision = config['styler']['format']['precision'] if precision is None else precision
        func_0 = partial(_default_formatter, precision=precision, thousands=thousands is not None)
    else:
        raise TypeError(f"'formatter' expected str or callable, got {type(formatter)}")
    if escape is not None:
        func_1 = lambda x: func_0(_str_escape(x, escape=escape))
    else:
        func_1 = func_0
    if field != '.' or (thousands is not None and thousands != ','):
        func_2 = _wrap_decimal_thousands(func_1, decimal=field, thousands=thousands)
    else:
        func_2 = func_1
    if hyperlinks is not None:
        func_3 = lambda x: func_2(_render_href(x, format=hyperlinks))
    else:
        func_3 = func_2
    if na_rep is None:
        return func_3
    else:
        return lambda x: na_rep if isna(x) is True else func_3(x)

def merge_hooks(request_hooks: _t.HooksType, session_hooks: _t.HooksType, dict_class: type=OrderedDict) -> _t.HooksType:
    """Properly merges both requests and session hooks.

    This is necessary because when request_hooks == {'response': []}, the
    merge breaks Session hooks entirely.
    """
    if session_hooks is None or session_hooks.get('response') == []:
        return request_hooks
    if request_hooks is None or request_hooks.get('response') == []:
        return session_hooks
    return merge_setting(request_hooks, session_hooks, dict_class)

@staticmethod
def _validate_curve_kwargs(n_curves, name, legend_metric, legend_metric_name, curve_kwargs, default_curve_kwargs=None, default_multi_curve_kwargs=None, param_73='1.9', **kwargs):
    """Get validated line kwargs for each curve.

        Parameters
        ----------
        n_curves : int
            Number of curves.

        name : list of str or None
            Name for labeling legend entries.

        legend_metric : dict
            Dictionary with "mean" and "std" keys, or "metric" key of metric
            values for each curve. If None, "label" will not contain metric values.

        legend_metric_name : str
            Name of the summary value provided in `legend_metrics`.

        curve_kwargs : dict or list of dict or None
            Dictionary with keywords passed to the matplotlib's `plot` function
            to draw the individual curves. If a list is provided, the
            parameters are applied to the curves sequentially. If a single
            dictionary is provided, the same parameters are applied to all
            curves.

        default_curve_kwargs : dict, default=None
            Default curve kwargs, to be added to all curves. Individual kwargs
            are over-ridden by `curve_kwargs`, if kwarg also set in `curve_kwargs`.

        default_multi_curve_kwargs : dict, default=None
            Default curve kwargs for multi-curve plots. Individual kwargs
            are over-ridden by `curve_kwargs`, if kwarg also set in `curve_kwargs`.

        removed_version : str, default="1.9"
            Version in which `kwargs` will be removed.

        **kwargs : dict
            Deprecated. Keyword arguments to be passed to matplotlib's `plot`.
        """
    if curve_kwargs and kwargs:
        raise ValueError(f'Cannot provide both `curve_kwargs` and `kwargs`. `**kwargs` is deprecated and will be removed in {param_73}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary.')
    if kwargs:
        warnings.warn(f'`**kwargs` is deprecated and will be removed in {param_73}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary instead.', FutureWarning)
        curve_kwargs = kwargs
    if isinstance(curve_kwargs, list) and len(curve_kwargs) != n_curves:
        raise ValueError(f'`curve_kwargs` must be None, a dictionary or a list of length {n_curves}. Got: {curve_kwargs}.')
    if isinstance(name, list) and len(name) != 1 and (not isinstance(curve_kwargs, list)):
        raise ValueError(f'To avoid labeling individual curves that have the same appearance, `curve_kwargs` should be a list of {n_curves} dictionaries. Alternatively, set `name` to `None` or a single string to label a single legend entry for all curves.')
    if isinstance(name, str):
        name = [name]
    if isinstance(name, list) and len(name) == 1:
        name = name * n_curves
    name = [None] * n_curves if name is None else name
    if isinstance(curve_kwargs, Mapping):
        curve_kwargs = [curve_kwargs] * n_curves
    elif curve_kwargs is None:
        curve_kwargs = [{}] * n_curves
    if default_curve_kwargs is None:
        default_curve_kwargs = {}
    if default_multi_curve_kwargs is None:
        default_multi_curve_kwargs = {}
    if n_curves > 1:
