@final
@classmethod
def _validate_frequency(cls, index, freq: BaseOffset, **kwargs) -> None:
    """
        Validate that a frequency is compatible with the values of a given
        Datetime Array/Index or Timedelta Array/Index

        Parameters
        ----------
        index : DatetimeIndex or TimedeltaIndex
            The index on which to determine if the given frequency is valid
        freq : DateOffset
            The frequency to validate
        """
    inferred = index._inferred_freq_str
    if index.size == 0 or inferred == freq.freqstr:
        return None
    try:
        on_freq = cls._generate_range(start=index[0], end=None, periods=len(index), freq=freq, unit=index.unit, **kwargs)
        if not lib.array_equivalent_bytes(index.asi8, on_freq.asi8):
            raise ValueError
    except ValueError as err:
        if 'non-fixed' in str(err):
            raise err
        raise ValueError(f'Inferred frequency {inferred} from passed values does not conform to passed frequency {freq.freqstr}') from err

def _get_counts(values_shape: Shape, mask: npt.NDArray[np.bool_] | None, axis: AxisInt | None, dtype: np.dtype[np.floating]=np.dtype(np.float64)) -> np.floating | npt.NDArray[np.floating]:
    """
    Get the count of non-null values along an axis

    Parameters
    ----------
    values_shape : tuple of int
        shape tuple from values ndarray, used if mask is None
    mask : Optional[ndarray[bool]]
        locations in values that should be considered missing
    axis : Optional[int]
        axis to count along
    dtype : type, optional
        type to use for count

    Returns
    -------
    count : scalar or array
    """
    if axis is None:
        if mask is not None:
            n = mask.size - mask.sum()
        else:
            n = np.prod(values_shape)
        return dtype.type(n)
    if mask is not None:
        count = mask.shape[axis] - mask.sum(axis)
    else:
        count = values_shape[axis]
    if is_integer(count):
        return dtype.type(count)
    return count.astype(dtype, copy=False)

@register.tag('get_language_info')
def do_get_language_info(parser, token):
    """
    Store the language information dictionary for the given language code in a
    context variable.

    Usage::

        {% get_language_info for LANGUAGE_CODE as l %}
        {{ l.code }}
        {{ l.name }}
        {{ l.name_translated }}
        {{ l.name_local }}
        {{ l.bidi|yesno:"bi-directional,uni-directional" }}
    """
    args = token.split_contents()
    if len(args) != 5 or args[1] != 'for' or args[3] != 'as':
        raise TemplateSyntaxError("'%s' requires 'for string as variable' (got %r)" % (args[0], args[1:]))
    return GetLanguageInfoNode(parser.compile_filter(args[2]), args[4])

@register.filter(is_safe=True, needs_autoescape=True)
def truncated_unordered_list(value, max_items, autoescape=True):
    """
    Render an unordered list, showing at most ``max_items`` items and a
    "...and N more objects." item at the end.

    Usage::

        {{ deleted_objects|truncated_unordered_list:100 }}
    """
    has_unlimited_items = max_items is None
    if not has_unlimited_items:
        max_items = int(max_items)
        if max_items <= 0:
            return mark_safe('')
    if autoescape:
        escaper = conditional_escape
    else:

        def escaper(x):
            return x
    item_count = 0

    def list_formatter(item_list, tabs=1):
        nonlocal item_count
        indent = '\t' * tabs
        output = []
        for item, children in _walk_items(item_list):
            sublist = ''
            item_count += 1
            should_display_item = has_unlimited_items or 0 < item_count <= max_items
            if children:
                sublist = '\n%s<ul>\n%s\n%s</ul>\n%s' % (indent, list_formatter(children, tabs + 1), indent, indent)
            if should_display_item:
                output.append('%s<li>%s%s</li>' % (indent, escaper(item), sublist))
        return '\n'.join(output)
    rendered_object_list = list_formatter(value)
    remaining_objects_message = ''
    if not has_unlimited_items and item_count > max_items:
        remaining_object_count = item_count - max_items
        remaining_objects_message = '\n\t<li>%s</li>' % (ngettext('…and %(count)d more object.', '…and %(count)d more objects.', remaining_object_count) % {'count': remaining_object_count})
    return mark_safe(rendered_object_list + remaining_objects_message)

