def pass_obj(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:
    """Similar to :func:`pass_context`, but only pass the object on the
    context onwards (:attr:`Context.obj`).  This is useful if that object
    represents the state of a nested system.
    """

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context().obj, *args, **kwargs)
    return update_wrapper(new_func, f)

def format_commands(self, target: Context, formatter: HelpFormatter) -> None:
    """Extra format methods for multi methods that adds all the commands
        after the options.
        """
    commands = []
    for subcommand in self.list_commands(target):
        cmd = self.get_command(target, subcommand)
        if cmd is None:
            continue
        if cmd.hidden:
            continue
        commands.append((subcommand, cmd))
    if len(commands):
        limit = formatter.width - 6 - max((len(cmd[0]) for cmd in commands))
        rows = []
        for subcommand, cmd in commands:
            help = cmd.get_short_help_str(limit)
            rows.append((subcommand, help))
        if rows:
            with formatter.section(_('Commands')):
                formatter.write_dl(rows)

def __set__(self, instance, value):
    """
        Retrieve the proxied geometry or raster with the corresponding class
        specified during initialization.

        To set geometries, use values of None, HEXEWKB, or WKT.
        To set rasters, use JSON or dict values.
        """
    gtype = self.field.geom_type
    if gtype == 'RASTER' and (value is None or isinstance(value, (str, dict, self._klass))):
        pass
    elif isinstance(value, self._klass):
        if value.srid is None:
            value.srid = self.field.srid
    elif value is None or isinstance(value, (str, memoryview)):
        pass
    else:
        raise TypeError('Cannot set %s SpatialProxy (%s) with value of type: %s' % (instance.__class__.__name__, gtype, type(value)))
    instance.__dict__[self.field.attname] = value
    return value

def clean(self, value):
    """
        Validate every value in the given list. A value is validated against
        the corresponding Field in self.fields.

        For example, if this MultiValueField was instantiated with
        fields=(DateField(), TimeField()), clean() would call
        DateField.clean(value[0]) and TimeField.clean(value[1]).
        """
    clean_data = []
    errors = []
    if self.disabled and (not isinstance(value, list)):
        value = self.widget.decompress(value)
    if not value or isinstance(value, (list, tuple)):
        if not value or not [v for v in value if v not in self.empty_values]:
            if self.required:
                raise ValidationError(self.error_messages['required'], code='required')
            else:
                return self.compress([])
    else:
        raise ValidationError(self.error_messages['invalid'], code='invalid')
    for i, field in enumerate(self.fields):
        try:
            field_value = value[i]
        except IndexError:
            field_value = None
        if field_value in self.empty_values:
            if self.require_all_fields:
                if self.required:
                    raise ValidationError(self.error_messages['required'], code='required')
            elif field.required:
                if field.error_messages['incomplete'] not in errors:
                    errors.append(field.error_messages['incomplete'])
                continue
        try:
            clean_data.append(field.clean(field_value))
        except ValidationError as e:
            errors.extend((m for m in e.error_list if m not in errors))
    if errors:
        raise ValidationError(errors)
    out = self.compress(clean_data)
    self.validate(out)
    self.run_validators(out)
    return out

def _pick_type(self, type_arg: t.Any, flag_value: t.Any, count: bool, is_flag: bool) -> types.ParamType[t.Any]:
    """Pick the final :class:`ParamType` for this option.

        :meth:`Parameter.__init__` already stored ``self.type`` from the explicit
        ``type`` argument or from ``default``. This method either returns that as-is, or
        overrides it for flag and count options (which are inferred from ``flag_value``
        rather than ``default``).
        """
    if type_arg is not None:
        return self.type
    if count:
        return types.IntRange(min=0)
    if not is_flag:
        return self.type
    if flag_value is UNSET or isinstance(flag_value, bool):
        return types.BoolParamType()
    guessed: types.ParamType[t.Any] = types.convert_type(None, flag_value)
    if isinstance(guessed, types.StringParamType) and (not isinstance(flag_value, str)) and (flag_value is not None):
        return types.UNPROCESSED
    return guessed

def response_action(self, request, queryset, action_location=ActionLocation.CHANGE_LIST):
    """
        Handle an admin action. Returns an HttpResponse if the action was
        handled, and None otherwise.
        """
    try:
        action_index = int(request.POST.get('index', 0))
    except ValueError:
        action_index = 0
    data = request.POST.copy()
    data.pop(helpers.ACTION_CHECKBOX_NAME, None)
    data.pop('index', None)
    try:
        data.update({'action': data.getlist('action')[action_index]})
    except IndexError:
        pass
    prefix = action_location.value if action_location != ActionLocation.CHANGE_LIST else ''
    action_form = self.action_form(data, auto_id=None, prefix=prefix)
    action_form.fields['action'].choices = self._get_action_choices_with_action_location(request, action_location=action_location)
    if action_form.is_valid():
        action = action_form.cleaned_data['action']
        select_across = action_form.cleaned_data['select_across']
        if action_location == ActionLocation.CHANGE_FORM:
            select_across = False
        actions = self._get_actions_with_action_location(request, action_location=action_location)
        if isinstance(actions[action], tuple):
            func = actions[action][0]
        else:
            func = actions[action].func
        selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)
        if not selected and (not select_across):
            msg = _('Items must be selected in order to perform actions on them. No items have been changed.')
            self.message_user(request, msg, messages.WARNING)
            return None
        if not select_across:
            queryset = queryset.filter(pk__in=selected)
        response = func(self, request, queryset)
        if isinstance(response, HttpResponseBase):
            return response
        else:
            return HttpResponseRedirect(request.get_full_path())
    else:
        msg = _('No action selected.')
        self.message_user(request, msg, messages.WARNING)
        return None

