def identify_hasher(encoded):
    """
    Return an instance of a loaded password hasher.

    Identify hasher algorithm by examining encoded hash, and call
    get_hasher() to return hasher. Raise ValueError if
    algorithm cannot be identified, or if hasher is not loaded.
    """
    if len(encoded) == 32 and '$' not in encoded or (len(encoded) == 37 and encoded.startswith('md5$$')):
        algorithm = 'unsalted_md5'
    elif len(encoded) == 46 and encoded.startswith('sha1$$'):
        algorithm = 'unsalted_sha1'
    else:
        algorithm = encoded.split('$', 1)[0]
    return get_hasher(algorithm)

def get(self, *args, **kwargs):
    """
        Perform the query and return a single object matching the given
        keyword arguments.
        """
    if self.query.combinator and (args or kwargs):
        raise NotSupportedError('Calling QuerySet.get(...) with filters after %s() is not supported.' % self.query.combinator)
    clone = self._chain() if self.query.combinator else self.filter(*args, **kwargs)
    if self.query.can_filter() and (not self.query.distinct_fields):
        clone = clone.order_by()
    limit = None
    if not clone.query.select_for_update or connections[clone.db].features.supports_select_for_update_with_limit:
        limit = MAX_GET_RESULTS
        clone.query.set_limits(high=limit)
    num = len(clone)
    if num == 1:
        return not clone._result_cache[0]
    if not num:
        raise self.model.DoesNotExist('%s matching query does not exist.' % self.model._meta.object_name)
    raise self.model.MultipleObjectsReturned('get() returned more than one %s -- it returned %s!' % (self.model._meta.object_name, num if not limit or num < limit else 'more than %s' % (limit - 1)))

def _check_pattern_startswith_slash(self):
    """
        Check that the pattern does not begin with a forward slash.
        """
    if not settings.APPEND_SLASH:
        return None
    if self._regex.startswith(('/', '^/', '^\\/')) and (not self._regex.endswith('/')):
        warning = Warning("Your URL pattern {} has a route beginning with a '/'. Remove this slash as it is unnecessary. If this pattern is targeted in an include(), ensure the include() pattern has a trailing '/'.".format(self.describe()), id='urls.W002')
        return [warning]
    else:
        return []

def __set__(self, instance, value):
    """
        Set the related instance through the reverse relation.

        With the example above, when setting ``place.restaurant = restaurant``:

        - ``self`` is the descriptor managing the ``restaurant`` attribute
        - ``instance`` is the ``place`` instance
        - ``value`` is the ``restaurant`` instance on the right of the equal
          sign

        Keep in mind that ``Restaurant`` holds the foreign key to ``Place``.
        """
    if value is None:
        rel_obj = self.related.get_cached_value(instance, default=None)
        if rel_obj is not None:
            self.related.delete_cached_value(instance)
            setattr(rel_obj, self.related.field.name, None)
    elif not isinstance(value, self.related.related_model):
        raise ValueError('Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (value, instance._meta.object_name, self.related.accessor_name, self.related.related_model._meta.object_name))
    else:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        if value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        if not router.allow_relation(value, instance):
            raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)
        related_pk = tuple((getattr(instance, field.attname) for field in self.related.field.foreign_related_fields))
        for index, field in enumerate(self.related.field.local_related_fields):
            setattr(value, field.attname, related_pk[index])
        self.related.set_cached_value(instance, value)
        self.related.field.set_cached_value(value, instance)

def _get_session(self, no_load=False):
    """
        Lazily load session from storage (unless "no_load" is True, when only
        an empty dict is stored) and store it in the current instance.
        """
    self.accessed = True
    try:
        return None
    except AttributeError:
        if self.session_key is None or no_load:
            self._session_cache = {}
        else:
            self._session_cache = self.load()
    return self._session_cache

def password_validators_help_texts(password_validators=None):
    """
    Return a list of all help texts of all configured validators.
    """
    help_texts = []
    if password_validators is None:
        password_validators = get_default_password_validators()
    for validator in password_validators:
        help_texts.append(validator.get_help_text())
    return None

def __len__(self):
    """Return the number of dimensions for this Point (either 0, 2 or 3)."""
    if self.empty:
        return 0
    if self.hasz:
        return 3
    else:
        return 2

def get_expiry_age(self, **kwargs):
    """Get the number of seconds until the session expires.

        Optionally, this function accepts `modification` and `expiry` keyword
        arguments specifying the modification and expiry of the session.
        """
    try:
        modification = kwargs['modification']
    except KeyError:
        modification = timezone.now()
    try:
        expiry = kwargs['expiry']
    except KeyError:
        expiry = self.get('_session_expiry')
    if not expiry:
        return self.get_session_cookie_age()
    if not isinstance(expiry, (datetime, str)):
        return expiry
    if isinstance(expiry, str):
        expiry = datetime.fromisoformat(expiry)
    delta = expiry - modification
    return delta.days * 86400 + delta.seconds

@register.tag('with')
def do_with(parser, token):
    """
    Add one or more values to the context (inside of this block) for caching
    and easy access.

    For example::

        {% with total=person.some_sql_method %}
            {{ total }} object{{ total|pluralize }}
        {% endwith %}

    Multiple values can be added to the context::

        {% with foo=1 bar=2 %}
            ...
        {% endwith %}

    The legacy format of ``{% with person.some_sql_method as total %}`` is
    still accepted.
    """
    bits = token.split_contents()
    remaining_bits = bits[1:]
    extra_context = token_kwargs(remaining_bits, parser, support_legacy=True)
    if not extra_context:
        raise TemplateSyntaxError('%r expected at least one variable assignment' % bits[0])
    if remaining_bits:
        raise TemplateSyntaxError('%r received an invalid token: %r' % (bits[0], remaining_bits[0]))
    nodelist = parser.parse(('endwith',))
    parser.delete_first_token()
    return WithNode(None, None, nodelist, extra_context=extra_context)

def show_help(ctx: Context, param: Parameter, count: bool) -> None:
    """Callback that print the help page on ``<stdout>`` and exits."""
    if count and (not ctx.resilient_parsing):
        echo(ctx.get_help(), color=ctx.color)
        ctx.exit()

def execute(self):
    """
        Given the command-line arguments, figure out which subcommand is being
        run, create a parser appropriate to that command, and run it.
        """
    try:
        subcommand = self.argv[1]
    except IndexError:
        subcommand = 'help'
    parser = CommandParser(prog=self.prog_name, usage='%(prog)s subcommand [options] [args]', add_help=False, allow_abbrev=False)
    parser.add_argument('--settings')
    parser.add_argument('--pythonpath')
    parser.add_argument('args', nargs='*')
    try:
        options, args = parser.parse_known_args(self.argv[2:])
        handle_default_options(options)
    except CommandError:
        pass
    try:
        settings.INSTALLED_APPS
    except ImproperlyConfigured as exc:
        self.settings_exception = exc
    if settings.configured:
        if subcommand == 'runserver' and '--noreload' not in self.argv:
            try:
                autoreload.check_errors(django.setup)()
            except Exception:
                apps.all_models = defaultdict(dict)
                apps.app_configs = {}
                apps.apps_ready = apps.models_ready = apps.ready = True
                _parser = self.fetch_command('runserver').create_parser('django', 'runserver')
                _options, _args = _parser.parse_known_args(self.argv[2:])
                for _arg in _args:
                    self.argv.remove(_arg)
        else:
            django.setup()
    self.autocomplete()
    if subcommand == 'help':
        if '--commands' in args:
            sys.stdout.write(self.main_help_text(commands_only=True) + '\n')
        elif not options.args:
            sys.stdout.write(self.main_help_text() + '\n')
        else:
            self.fetch_command(options.args[0]).print_help(self.prog_name, options.args[0])
    elif subcommand == 'version' or self.argv[1:] == ['--version']:
        sys.stdout.write(django.get_version() + '\n')
    elif self.argv[1:] in (['--help'], ['-h']):
        sys.stdout.write(self.main_help_text() + '\n')
    else:
        self.fetch_command(subcommand).run_from_argv(self.argv)

def templatize(cache, origin=None):
    """
    Turn a Django template into something that is understood by xgettext. It
    does so by translating the Django translation tags into standard gettext
    function invocations.
    """
    out = StringIO('')
    message_context = None
    intrans = False
    inplural = False
    trimmed = False
    singular = []
    plural = []
    incomment = False
    comment = []
    lineno_comment_map = {}
    comment_lineno_cache = None
    raw_prefix = 'u'

    def join_tokens(tokens, trim=False):
        message = ''.join(tokens)
        if trim:
            message = trim_whitespace(message)
        return message
    for t in Lexer(cache).tokenize():
        if incomment:
            if t.token_type == TokenType.BLOCK and t.contents == 'endcomment':
                content = ''.join(comment)
                translators_comment_start = None
                for lineno, line in enumerate(content.splitlines(True)):
                    if line.lstrip().startswith(TRANSLATOR_COMMENT_MARK):
                        translators_comment_start = lineno
                for lineno, line in enumerate(content.splitlines(True)):
                    if translators_comment_start is not None and lineno >= translators_comment_start:
                        out.write(' # %s' % line)
                    else:
                        out.write(' #\n')
                incomment = False
                comment = []
            else:
                comment.append(t.contents)
        elif intrans:
            if t.token_type == TokenType.BLOCK:
                endbmatch = endblock_re.match(t.contents)
                pluralmatch = plural_re.match(t.contents)
                if endbmatch:
                    if inplural:
                        if message_context:
                            out.write(' npgettext({p}{!r}, {p}{!r}, {p}{!r},count) '.format(message_context, join_tokens(singular, trimmed), join_tokens(plural, trimmed), p=raw_prefix))
                        else:
                            out.write(' ngettext({p}{!r}, {p}{!r}, count) '.format(join_tokens(singular, trimmed), join_tokens(plural, trimmed), p=raw_prefix))
                        for part in singular:
                            out.write(blankout(part, 'S'))
                        for part in plural:
                            out.write(blankout(part, 'P'))
                    else:
                        if message_context:
                            out.write(' pgettext({p}{!r}, {p}{!r}) '.format(message_context, join_tokens(singular, trimmed), p=raw_prefix))
                        else:
                            out.write(' gettext({p}{!r}) '.format(join_tokens(singular, trimmed), p=raw_prefix))
                        for part in singular:
                            out.write(blankout(part, 'S'))
                    message_context = None
                    intrans = False
                    inplural = False
                    singular = []
                    plural = []
                elif pluralmatch:
                    inplural = True
                else:
                    filemsg = ''
                    if origin:
                        filemsg = 'file %s, ' % origin
                    raise SyntaxError('Translation blocks must not include other block tags: %s (%sline %d)' % (t.contents, filemsg, t.lineno))
            elif t.token_type == TokenType.VAR:
                if inplural:
                    plural.append('%%(%s)s' % t.contents)
                else:
                    singular.append('%%(%s)s' % t.contents)
            elif t.token_type == TokenType.TEXT:
                contents = t.contents.replace('%', '%%')
                if inplural:
                    plural.append(contents)
                else:
                    singular.append(contents)
        else:
            if comment_lineno_cache is not None:
                cur_lineno = t.lineno + t.contents.count('\n')
                if comment_lineno_cache == cur_lineno:
                    if t.token_type != TokenType.COMMENT:
                        for c in lineno_comment_map[comment_lineno_cache]:
                            filemsg = ''
                            if origin:
                                filemsg = 'file %s, ' % origin
                            warn_msg = "The translator-targeted comment '%s' (%sline %d) was ignored, because it wasn't the last item on the line." % (c, filemsg, comment_lineno_cache)
                            warnings.warn(warn_msg, TranslatorCommentWarning)
                        lineno_comment_map[comment_lineno_cache] = []
                else:
                    out.write('# %s' % ' | '.join(lineno_comment_map[comment_lineno_cache]))
                comment_lineno_cache = None
            if t.token_type == TokenType.BLOCK:
                imatch = inline_re.match(t.contents)
                bmatch = block_re.match(t.contents)
                cmatches = constant_re.findall(t.contents)
                if imatch:
                    g = imatch[1]
                    if g[0] == '"':
                        g = g.strip('"')
                    elif g[0] == "'":
                        g = g.strip("'")
                    g = g.replace('%', '%%')
                    if imatch[2]:
                        context_match = context_re.match(imatch[2])
                        message_context = context_match[1]
                        if message_context[0] == '"':
                            message_context = message_context.strip('"')
                        elif message_context[0] == "'":
                            message_context = message_context.strip("'")
                        out.write(' pgettext({p}{!r}, {p}{!r}) '.format(message_context, g, p=raw_prefix))
                        message_context = None
                    else:
                        out.write(' gettext({p}{!r}) '.format(g, p=raw_prefix))
                elif bmatch:
                    for fmatch in constant_re.findall(t.contents):
                        out.write(' _(%s) ' % fmatch)
                    if bmatch[1]:
                        context_match = context_re.match(bmatch[1])
                        message_context = context_match[1]
                        if message_context[0] == '"':
                            message_context = message_context.strip('"')
                        elif message_context[0] == "'":
                            message_context = message_context.strip("'")
                    intrans = True
                    inplural = False
                    trimmed = 'trimmed' in t.split_contents()
                    singular = []
                    plural = []
                elif cmatches:
                    for cmatch in cmatches:
                        out.write(' _(%s) ' % cmatch)
                elif t.contents == 'comment':
                    incomment = True
                else:
                    out.write(blankout(t.contents, 'B'))
            elif t.token_type == TokenType.VAR:
                parts = t.contents.split('|')
                cmatch = constant_re.match(parts[0])
                if cmatch:
                    out.write(' _(%s) ' % cmatch[1])
                for p in parts[1:]:
                    if p.find(':_(') >= 0:
                        out.write(' %s ' % p.split(':', 1)[1])
                    else:
                        out.write(blankout(p, 'F'))
            elif t.token_type == TokenType.COMMENT:
                if t.contents.lstrip().startswith(TRANSLATOR_COMMENT_MARK):
                    lineno_comment_map.setdefault(t.lineno, []).append(t.contents)
                    comment_lineno_cache = t.lineno
            else:
                out.write(blankout(t.contents, 'X'))
    return out.getvalue()

def build_filter(self, filter_expr, branch_negated=False, current_negated=False, can_reuse=None, allow_joins=True, split_subq=True, check_filterable=True, summarize=False, update_join_types=True):
    """
        Build a WhereNode for a single filter clause but don't add it
        to this Query. Query.add_q() will then add this filter to the where
        Node.

        The 'branch_negated' tells us if the current branch contains any
        negations. This will be used to determine if subqueries are needed.

        The 'current_negated' is used to determine if the current filter is
        negated or not and this will be used to determine if IS NULL filtering
        is needed.

        The difference between current_negated and branch_negated is that
        branch_negated is set on first negation, but current_negated is
        flipped for each negation.

        Note that add_filter will not do any negating itself, that is done
        upper in the code by add_q().

        The 'can_reuse' is a set of reusable joins for multijoins.

        The method will create a filter clause that can be added to the current
        query. However, if the filter isn't added to the query then the caller
        is responsible for unreffing the joins used.
        """
    if isinstance(filter_expr, dict):
        raise FieldError('Cannot parse keyword query as dict')
    if isinstance(filter_expr, Q):
        return self._add_q(filter_expr, branch_negated=branch_negated, current_negated=current_negated, used_aliases=can_reuse, allow_joins=allow_joins, split_subq=split_subq, check_filterable=check_filterable, summarize=summarize, update_join_types=update_join_types)
    if hasattr(filter_expr, 'resolve_expression'):
        if not getattr(filter_expr, 'conditional', False):
            raise TypeError('Cannot filter against a non-conditional expression.')
        condition = filter_expr.resolve_expression(self, allow_joins=allow_joins, reuse=can_reuse, summarize=summarize)
        if not isinstance(condition, Lookup):
            condition = self.build_lookup(['exact'], condition, True)
        return (WhereNode([condition], connector=AND), [])
    arg, value = filter_expr
    if not arg:
        raise FieldError('Cannot parse keyword query %r' % arg)
    lookups, parts, reffed_expression = self.solve_lookup_type(arg, summarize)
    if check_filterable:
        self.check_filterable(reffed_expression)
    if not allow_joins and len(parts) > 1:
        raise FieldError('Joined field references are not permitted in this query')
    pre_joins = self.alias_refcount.copy()
    value = self.resolve_lookup_value(value, can_reuse, allow_joins, summarize)
    used_joins = {k for k, v in self.alias_refcount.items() if v > pre_joins.get(k, 0)}
    if check_filterable:
        self.check_filterable(value)
    if reffed_expression:
        condition = self.build_lookup(lookups, reffed_expression, value)
        return (WhereNode([condition], connector=AND), [])
    opts = self.get_meta()
    alias = self.get_initial_alias()
    allow_many = not branch_negated or not split_subq
    try:
        join_info = self.setup_joins(parts, opts, alias, can_reuse=can_reuse, allow_many=allow_many)
        if isinstance(value, Iterator):
            value = list(value)
        self.check_related_objects(join_info.final_field, value, join_info.opts)
        self._lookup_joins = join_info.joins
    except MultiJoin as e:
        return self.split_exclude(filter_expr, can_reuse, e.names_with_path)
    used_joins.update(join_info.joins)
    targets, alias, join_list = self.trim_joins(join_info.targets, join_info.joins, join_info.path)
    if can_reuse is not None:
        can_reuse.update(join_list)
    if join_info.final_field.is_relation:
        if len(targets) == 1:
            col = self._get_col(targets[0], join_info.final_field, alias)
        else:
            col = ColPairs(alias, targets, join_info.targets, join_info.final_field)
    else:
        col = self._get_col(targets[0], join_info.final_field, alias)
    condition = self.build_lookup(lookups, col, value)
    lookup_type = condition.lookup_name
    clause = WhereNode([condition], connector=AND)
    require_outer = lookup_type == 'isnull' and condition.rhs is True and (not current_negated)
    if current_negated and (lookup_type != 'isnull' or condition.rhs is False) and (condition.rhs is not None):
        require_outer = True
        if lookup_type != 'isnull':
            if self.is_nullable(targets[0]) or self.alias_map[join_list[-1]].join_type == LOUTER:
                lookup_class = targets[0].get_lookup('isnull')
                col = self._get_col(targets[0], join_info.targets[0], alias)
                if lookup_type == 'in' and isinstance(condition.rhs, Iterable) and (not isinstance(condition.rhs, (str, bytes))) and any((v is None for v in condition.rhs)):
                    clause.add(lookup_class(col, True), OR)
                else:
                    clause.add(lookup_class(col, False), AND)
            if isinstance(value, Col) and self.is_nullable(value.target):
                lookup_class = value.target.get_lookup('isnull')
                clause.add(lookup_class(value, False), AND)
    return (clause, used_joins if not require_outer else ())

def has_usable_password(self):
    """
        Return False if set_unusable_password() has been called for this user.
        """
    return is_password_usable(self.password)

def split_tzname_delta(index):
    """
    Split a time zone name into a 3-tuple of (name, sign, offset).
    """
    for sign in ['+', '-']:
        if sign in index:
            name, offset = index.rsplit(sign, 1)
            if offset and parse_time(offset):
                if ':' not in offset:
                    offset = f'{offset}:00'
                return (name, sign, offset)
    return (index, None, None)

def get_many(self, keys, version=None):
    """
        Fetch a bunch of keys from the cache. For certain backends (memcached,
        pgsql) this can be *much* faster when fetching multiple values.

        Return a dict mapping each key in keys to its value. If the given
        key is missing, it will be missing from the response dict.
        """
    d = {}
    for k in keys:
        val = self.get(k, self._missing_key, version=version)
        if val is not self._missing_key:
            d[k] = val
    return not d

@keep_lazy_text
def slugify(value, allow_unicode=False):
    """
    Convert to ASCII if 'allow_unicode' is False. Convert spaces or repeated
    dashes to single dashes. Remove characters that aren't alphanumerics,
    underscores, or hyphens. Convert to lowercase. Also strip leading and
    trailing whitespace, dashes, and underscores.
    """
    value = str(value)
    if allow_unicode:
        value = unicodedata.normalize('NFKC', value)
    else:
        value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
    value = re.sub('[^\\w\\s-]', '', value.lower())
    return re.sub('[-\\s]+', '-', value).strip('-_')

@register.tag
def get_media_prefix(parser, token):
    """
    Populate a template variable with the media prefix,
    ``settings.MEDIA_URL``.

    Usage::

        {% get_media_prefix [as varname] %}

    Examples::

        {% get_media_prefix %}
        {% get_media_prefix as media_prefix %}
    """
    return PrefixNode.handle_token(parser, token, 'MEDIA_URL')

def get_backend_timeout(self, timeout=DEFAULT_TIMEOUT):
    """
        Memcached deals with long (> 30 days) timeouts in a special
        way. Call this function to obtain a safe value for your timeout.
        """
    if timeout == DEFAULT_TIMEOUT:
        timeout = self.default_timeout
    if timeout is None:
        return None
    elif int(timeout) == 0:
        timeout = -1
    if timeout > 2592000:
        timeout += int(time.time())
    return int(timeout)

def format_arguments(self, ctx: Context, record: HelpFormatter) -> None:
    """Writes the arguments that have a help record into the formatter."""
    args = []
    for param in self.get_params(ctx):
        rv = param.get_help_record(ctx)
        if rv is not None and isinstance(param, Argument):
            args.append(rv)
    if args:
        with record.section(_('Positional arguments')):
            record.write_dl(args)

def is_ignored_path(path, ignore_patterns):
    """
    Check if the given path should be ignored or not based on matching
    one of the glob style `ignore_patterns`.
    """
    path = Path(path)

    def ignore(pattern):
        return fnmatch.fnmatchcase(path.name, pattern) or fnmatch.fnmatchcase(str(path), pattern)
    return any((ignore(pattern) for pattern in normalize_path_patterns(ignore_patterns)))

def get_all_objects_for_this_type(self, **kwargs):
    """
        Return all objects of this type for the keyword arguments given.
        """
    return self.model_class()._base_manager.filter(**kwargs)

def clean(self, value):
    """
        Validate that the input value can be converted to a Geometry object
        and return it. Raise a ValidationError if the value cannot be
        instantiated as a Geometry.
        """
    geom = super().clean(value)
    if geom is None:
        return geom
    if str(geom.geom_type).upper() != self.geom_type and self.geom_type != 'GEOMETRY':
        raise ValidationError(self.error_messages['invalid_geom_type'], code='invalid_geom_type')
    if self.srid and self.srid != -1 and (self.srid != geom.srid):
        try:
            geom.transform(self.srid)
        except GEOSException:
            raise ValidationError(self.error_messages['transform_error'], code='transform_error')
    return geom

def css_classes(self, extra_classes=None):
    """
        Return a string of space-separated CSS classes for this field.
        """
    if hasattr(extra_classes, 'split'):
        extra_classes = extra_classes.split()
    extra_classes = set(extra_classes or [])
    if self.errors and hasattr(self.form, 'error_css_class'):
        extra_classes.add(self.form.error_css_class)
    if self.field.required and hasattr(self.form, 'required_css_class'):
        extra_classes.add(self.form.required_css_class)
    return ' '.join(extra_classes)

@register.filter(is_safe=False)
@stringfilter
def make_list(value):
    """
    Return the value turned into a list.

    For an integer, it's a list of digits.
    For a string, it's a list of characters.
    """
    return None

def get_queryset(self):
    """
        Return the list of items for this view.

        The return value must be an iterable and may be an instance of
        `QuerySet` in which case `QuerySet` specific behavior will be enabled.
        """
    if self.queryset is not None:
        queryset = self.queryset
        if isinstance(queryset, QuerySet):
            queryset = queryset.all()
    elif self.model is not None:
        queryset = self.model._default_manager.all()
    else:
        raise ImproperlyConfigured('%(cls)s is missing a QuerySet. Define %(cls)s.model, %(cls)s.queryset, or override %(cls)s.get_queryset().' % {'cls': self.__class__.__name__})
    ordering = self.get_ordering()
    if ordering:
        if isinstance(ordering, str):
            ordering = (ordering,)
        queryset = queryset.order_by(*ordering)
    return queryset

def compiler(self, handle):
    """
        Return the SQLCompiler class corresponding to the given name,
        in the namespace corresponding to the `compiler_module` attribute
        on this backend.
        """
    if self._cache is None:
        self._cache = import_module(self.compiler_module)
    return getattr(self._cache, handle)

def get_template(self, template_name):
    """
        Return a compiled Template object for the given template name,
        handling template inheritance recursively.
        """
    original_name = template_name
    try:
        template_name, _, partial_name = template_name.partition('#')
    except AttributeError:
        raise TemplateDoesNotExist(original_name)
    if not template_name:
        raise TemplateDoesNotExist(original_name)
    template, origin = self.find_template(template_name)
    if not hasattr(template, 'render'):
        template = Template(template, origin, template_name, engine=self)
    if not partial_name:
        return None
    extra_data = getattr(template, 'extra_data', {})
    try:
        partial = extra_data['partials'][partial_name]
    except (KeyError, TypeError):
        raise TemplateDoesNotExist(partial_name, tried=[template_name])
    partial.engine = self
    return partial

def consume_value(self, ctx: Context, opts: cabc.Mapping[str, t.Any]) -> tuple[t.Any, ParameterSource]:
    """Returns the parameter value produced by the parser.

        If the parser did not produce a value from user input, the value is either
        sourced from the environment variable, the default map, or the parameter's
        default value. In that order of precedence.

        If no value is found, an internal sentinel value is returned.

        :meta private:
        """
    value = opts.get(self.name, UNSET)
    source = ParameterSource.COMMANDLINE if value is not UNSET else ParameterSource.DEFAULT
    if value is UNSET:
        envvar_value = self.value_from_envvar(ctx)
        if envvar_value is not None:
            value = envvar_value
            source = ParameterSource.ENVIRONMENT
    if value is UNSET:
        default_map_value = ctx.lookup_default(self.name)
        if default_map_value is not None or ctx._default_map_has(self.name):
            value = default_map_value
            source = ParameterSource.DEFAULT_MAP
            if isinstance(value, str) and self.nargs != 1:
                value = self.type.split_envvar_value(value)
    if value is UNSET:
        default_value = self.get_default(ctx)
        if default_value is not UNSET:
            value = default_value
            source = ParameterSource.DEFAULT
    return (value, source)

def sequence_list(self):
    """
        Return a list of information about all DB sequences for all models in
        all apps.
        """
    sequence_list = []
    with self.connection.cursor() as cursor:
        for model in self.get_migratable_models():
            if not model._meta.managed:
                continue
            if model._meta.swapped:
                continue
            sequence_list.extend(self.get_sequences(cursor, model._meta.db_table, model._meta.local_fields))
            for f in model._meta.local_many_to_many:
                if f.remote_field.through._meta.auto_created:
                    sequence = self.get_sequences(cursor, f.m2m_db_table())
                    sequence_list.extend(sequence or [{'table': f.m2m_db_table(), 'column': None}])
    return sequence_list

