def get_constraints(self, session, table_name):
    """
        Retrieve any constraints or keys (unique, pk, fk, check, index) across
        one or more columns.
        """
    constraints = {}
    name_query = "\n            SELECT kc.`constraint_name`, kc.`column_name`,\n                kc.`referenced_table_name`, kc.`referenced_column_name`,\n                c.`constraint_type`\n            FROM\n                information_schema.key_column_usage AS kc,\n                information_schema.table_constraints AS c\n            WHERE\n                kc.table_schema = DATABASE() AND\n                (\n                    kc.referenced_table_schema = DATABASE() OR\n                    kc.referenced_table_schema IS NULL\n                ) AND\n                c.table_schema = kc.table_schema AND\n                c.constraint_name = kc.constraint_name AND\n                c.constraint_type != 'CHECK' AND\n                kc.table_name = %s\n            ORDER BY kc.`ordinal_position`\n        "
    session.execute(name_query, [table_name])
    for constraint, column, ref_table, ref_column, kind in session.fetchall():
        if constraint not in constraints:
            constraints[constraint] = {'columns': OrderedSet(), 'primary_key': kind == 'PRIMARY KEY', 'unique': kind in {'PRIMARY KEY', 'UNIQUE'}, 'index': False, 'check': False, 'foreign_key': (ref_table, ref_column) if ref_column else None}
            if self.connection.features.supports_index_column_ordering:
                constraints[constraint]['orders'] = []
        constraints[constraint]['columns'].add(column)
    if self.connection.features.can_introspect_check_constraints:
        unnamed_constraints_index = 0
        columns = {info.name for info in self.get_table_description(session, table_name)}
        if self.connection.mysql_is_mariadb:
            type_query = '\n                    SELECT c.constraint_name, c.check_clause\n                    FROM information_schema.check_constraints AS c\n                    WHERE\n                        c.constraint_schema = DATABASE() AND\n                        c.table_name = %s\n                '
        else:
            type_query = "\n                    SELECT cc.constraint_name, cc.check_clause\n                    FROM\n                        information_schema.check_constraints AS cc,\n                        information_schema.table_constraints AS tc\n                    WHERE\n                        cc.constraint_schema = DATABASE() AND\n                        tc.table_schema = cc.constraint_schema AND\n                        cc.constraint_name = tc.constraint_name AND\n                        tc.constraint_type = 'CHECK' AND\n                        tc.table_name = %s\n                "
        session.execute(type_query, [table_name])
        for constraint, check_clause in session.fetchall():
            constraint_columns = self._parse_constraint_columns(check_clause, columns)
            if set(constraint_columns) == {constraint}:
                unnamed_constraints_index += 1
                constraint = '__unnamed_constraint_%s__' % unnamed_constraints_index
            constraints[constraint] = {'columns': constraint_columns, 'primary_key': False, 'unique': False, 'index': False, 'check': True, 'foreign_key': None}
    session.execute('SHOW INDEX FROM %s' % self.connection.ops.quote_name(table_name))
    for table, non_unique, index, colseq, column, order, type_ in [x[:6] + (x[10],) for x in session.fetchall()]:
        if index not in constraints:
            constraints[index] = {'columns': OrderedSet(), 'primary_key': False, 'unique': not non_unique, 'check': False, 'foreign_key': None}
            if self.connection.features.supports_index_column_ordering:
                constraints[index]['orders'] = []
        constraints[index]['index'] = True
        constraints[index]['type'] = Index.suffix if type_ == 'BTREE' else type_.lower()
        constraints[index]['columns'].add(column)
        if self.connection.features.supports_index_column_ordering:
            constraints[index]['orders'].append('DESC' if order == 'D' else 'ASC')
    for constraint in constraints.values():
        constraint['columns'] = list(constraint['columns'])
    return constraints

@register.tag
def get_admin_log(parser, token):
    """
    Populate a template variable with the admin log for the given criteria.

    Usage::

        {% get_admin_log [limit] as [varname] for_user [user_id_or_varname] %}

    Examples::

        {% get_admin_log 10 as admin_log for_user 23 %}
        {% get_admin_log 10 as admin_log for_user user %}
        {% get_admin_log 10 as admin_log %}

    Note that ``user_id_or_varname`` can be a hard-coded integer (user ID)
    or the name of a template context variable containing the user object
    whose ID you want.
    """
    tokens = token.contents.split()
    if len(tokens) < 4:
        raise template.TemplateSyntaxError("'get_admin_log' statements require two arguments")
    if not tokens[1].isdigit():
        raise template.TemplateSyntaxError("First argument to 'get_admin_log' must be an integer")
    if tokens[2] != 'as':
        raise template.TemplateSyntaxError("Second argument to 'get_admin_log' must be 'as'")
    if len(tokens) > 4:
        if tokens[4] != 'for_user':
            raise template.TemplateSyntaxError("Fourth argument to 'get_admin_log' must be 'for_user'")
    return AdminLogNode(limit=tokens[1], varname=tokens[3], user=tokens[5] if len(tokens) > 5 else None)

def conditional_escape(text):
    """
    Similar to escape(), except that it doesn't operate on pre-escaped strings.

    This function relies on the __html__ convention used both by Django's
    SafeData class and by third-party libraries like markupsafe.
    """
    if isinstance(text, Promise):
        text = str(text)
    if hasattr(text, '__html__'):
        return text.__html__()
    else:
        return escape(text)

def bulk_update(self, objs, fields, batch_size=None):
    """
        Update the given fields in each of the given objects in the database.
        """
    if batch_size is not None and batch_size <= 0:
        raise ValueError('Batch size must be a positive integer.')
    if not fields:
        raise ValueError('Field names must be given to bulk_update().')
    objs = tuple(objs)
    if not all((obj._is_pk_set() for obj in objs)):
        raise ValueError('All bulk_update() objects must have a primary key set.')
    opts = self.model._meta
    fields = [opts.get_field(name) for name in fields]
    if any((not f.concrete for f in fields)):
        raise ValueError('bulk_update() can only be used with concrete fields.')
    all_pk_fields = set(opts.pk_fields)
    for parent in opts.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    if any((f in all_pk_fields for f in fields)):
        raise ValueError('bulk_update() cannot be used with primary key fields.')
    if not objs:
        return 0
    for obj in objs:
        obj._prepare_related_fields_for_save(operation_name='bulk_update', fields=fields)
    self._for_write = True
    connection = connections[self.db]
    max_batch_size = connection.ops.bulk_batch_size([opts.pk, opts.pk, *fields], objs)
    batch_size = min(batch_size, max_batch_size) if batch_size else max_batch_size
    requires_casting = connection.features.requires_casted_case_in_updates
    batches = (objs[i:i + batch_size] for i in range(0, len(objs), batch_size))
    updates = []
    for batch_objs in batches:
        update_kwargs = {}
        for field in fields:
            when_statements = []
            for obj in batch_objs:
                attr = getattr(obj, field.attname)
                if not hasattr(attr, 'resolve_expression'):
                    attr = Value(attr, output_field=field)
                when_statements.append(When(pk=obj.pk, then=attr))
            case_statement = Case(*when_statements, output_field=field)
            if requires_casting:
                case_statement = Cast(case_statement, output_field=field)
            update_kwargs[field.attname] = case_statement
        updates.append(([obj.pk for obj in batch_objs], update_kwargs))
    rows_updated = 0
    queryset = self.using(self.db)
    with transaction.atomic(using=self.db, savepoint=False):
        for pks, update_kwargs in updates:
            rows_updated += queryset.filter(pk__in=pks).update(**update_kwargs)
    return rows_updated

def parse_datetime(value):
    """Parse a string and return a datetime.datetime.

    This function supports time zone offsets. When the input contains one,
    the output uses a timezone with a fixed offset from UTC.

    Raise ValueError if the input is well formatted but not a valid datetime.
    Return None if the input isn't well formatted.
    """
    try:
        return datetime.datetime.fromisoformat(value)
    except ValueError:
        if (match := datetime_re.match(value)):
            kw = match.groupdict()
            kw['microsecond'] = kw['microsecond'] and kw['microsecond'].ljust(6, '0')
            tzinfo = kw.pop('tzinfo')
            if tzinfo == 'Z':
                tzinfo = datetime.UTC
            elif tzinfo is not None:
                offset_mins = int(tzinfo[-2:]) if len(tzinfo) > 3 else 0
                offset = 60 * int(tzinfo[1:3]) + offset_mins
                if tzinfo[0] == '-':
                    offset = -offset
                tzinfo = get_fixed_timezone(offset)
            kw = {k: int(v) for k, v in kw.items() if v is not None}
            return datetime.datetime(**kw, tzinfo=tzinfo)

def cursor_iter(cursor, sentinel, param_28, itersize):
