def _alter_column_default_sql(self, model, old_field, new_field, drop=False):
    """
        Hook to specialize column default alteration.

        Return a (sql, params) fragment to add or drop (depending on the drop
        argument) a default to new_field's column.
        """
    new_default = self.effective_default(new_field)
    default = self._column_default_sql(new_field)
    params = [new_default]
    if drop:
        params = []
    elif self.connection.features.requires_literal_defaults:
        default = self.prepare_default(new_default)
        params = []
    new_db_params = new_field.db_parameters(connection=self.connection)
    if drop:
        if new_field.null:
            sql = self.sql_alter_column_no_default_null
        else:
            sql = self.sql_alter_column_no_default
    else:
        sql = self.sql_alter_column_default
    return (sql % {'column': self.quote_name(new_field.column), 'type': new_db_params['type'], 'default': default}, params)

@functools.lru_cache
def _route_to_regex(route, is_endpoint):
    """
    Convert a path pattern into a regular expression. Return the regular
    expression and a dictionary mapping the capture names to the converters.
    For example, 'foo/<int:pk>' returns '^foo\\/(?P<pk>[0-9]+)'
    and {'pk': <django.urls.converters.IntConverter>}.
    """
    parts = ['^']
    all_converters = get_converters()
    converters = {}
    previous_end = 0
    for match_ in _PATH_PARAMETER_COMPONENT_RE.finditer(route):
        if not whitespace_set.isdisjoint(match_[0]):
            raise ImproperlyConfigured(f'URL route {route!r} cannot contain whitespace in angle brackets <…>.')
        raw_converter, parameter = match_.groups(default='str')
        if not parameter.isidentifier():
            raise ImproperlyConfigured(f"URL route {route!r} uses parameter name {parameter!r} which isn't a valid Python identifier.")
        try:
            converter = all_converters[raw_converter]
        except KeyError as e:
            raise ImproperlyConfigured(f'URL route {route!r} uses invalid converter {raw_converter!r}.') from e
        converters[parameter] = converter
        start, end = match_.span()
        parts.append(re.escape(route[previous_end:start]))
        previous_end = end
        parts.append(f'(?P<{parameter}>{converter.regex})')
    parts.append(re.escape(route[previous_end:]))
    if is_endpoint:
        parts.append('\\Z')
    return (''.join(parts), converters)

def _build_kml_sources(self, sources):
    """
        Go through the given sources and return a 3-tuple of the application
        label, module name, and field name of every GeometryField encountered
        in the sources.

        If no sources are provided, then all models.
        """
    kml_sources = []
    if sources is None:
        sources = apps.get_models()
    for source in sources:
        if isinstance(source, models.base.ModelBase):
            for field in source._meta.fields:
                if isinstance(field, GeometryField):
                    kml_sources.append((source._meta.app_label, source._meta.model_name, field.name))
        elif isinstance(source, (list, tuple)):
            if len(source) != 3:
                raise ValueError('Must specify a 3-tuple of (app_label, module_name, field_name).')
            kml_sources.append(source)
        else:
            raise TypeError('KML Sources must be a model or a 3-tuple.')
    return kml_sources

