        if formfield and db_field.name not in self.raw_id_fields:
            try:
                related_modeladmin = self.admin_site.get_model_admin(db_field.remote_field.model)
            except NotRegistered:
                wrapper_kwargs = {}
            else:
                wrapper_kwargs = {'can_add_related': related_modeladmin.has_add_permission(request), 'can_change_related': related_modeladmin.has_change_permission(request), 'can_delete_related': related_modeladmin.has_delete_permission(request), 'can_view_related': related_modeladmin.has_view_permission(request)}
            formfield.widget = widgets.RelatedFieldWidgetWrapper(formfield.widget, db_field.remote_field, self.admin_site, **wrapper_kwargs)
        return formfield
    for klass in db_field.__class__.mro():
        if klass in self.formfield_overrides:
            kwargs = {**copy.deepcopy(self.formfield_overrides[klass]), **kwargs}
            return db_field.formfield(**kwargs)
    return db_field.formfield(**kwargs)

def __getstate__(self):
    """
        Raise an exception if trying to pickle an unrendered response. Pickle
        only rendered data, not the data used to construct the response.
        """
    obj_dict = self.__dict__.copy()
    if not self._is_rendered:
        raise ContentNotRenderedError('The response content must be rendered before it can be pickled.')
    for attr in self.rendering_attrs:
        if attr in obj_dict:
            del obj_dict[attr]
    return obj_dict

def get_child_arguments():
    """
    Return the executable. This contains a workaround for Windows if the
    executable is reported to not have the .exe extension which can cause bugs
    on reloading.
    """
    import __main__
    py_script = Path(sys.argv[0])
    exe_entrypoint = py_script.with_suffix('.exe')
    args = [sys.executable] + ['-W%s' % o for o in sys.warnoptions]
    if sys.implementation.name in ('cpython', 'pypy'):
        args.extend((f'-X{key}' if value is True else f'-X{key}={value}' for key, value in sys._xoptions.items()))
    if getattr(__main__, '__spec__', None) is not None and (not exe_entrypoint.exists()):
        spec = __main__.__spec__
        if (spec.name == '__main__' or spec.name.endswith('.__main__')) and spec.parent:
            name = spec.parent
        else:
            name = spec.name
        args += ['-m', name]
        args += sys.argv[1:]
    elif not py_script.exists():
        if exe_entrypoint.exists():
            return [exe_entrypoint, *sys.argv[1:]]
        script_entrypoint = py_script.with_name('%s-script.py' % py_script.name)
        if script_entrypoint.exists():
            return [*args, script_entrypoint, *sys.argv[1:]]
        raise RuntimeError('Script %s does not exist.' % py_script)
    else:
        args += sys.argv
    return args

