def get_constraints(self, handle, table_name):
    """
        Retrieve any constraints or keys (unique, pk, fk, check, index) across
        one or more columns.
        """
    constraints = {}
    try:
        table_schema = handle.execute("SELECT sql FROM sqlite_master WHERE type='table' and name=%s", [table_name]).fetchone()[0]
    except TypeError:
        pass
    else:
        columns = {info.name for info in self.get_table_description(handle, table_name)}
        constraints.update(self._parse_table_constraints(table_schema, columns))
    handle.execute('PRAGMA index_list(%s)' % self.connection.ops.quote_name(table_name))
    for row in handle.fetchall():
        number, index, unique = row[:3]
        handle.execute("SELECT sql FROM sqlite_master WHERE type='index' AND name=%s", [index])
        sql, = handle.fetchone() or (None,)
        if not sql:
            continue
        handle.execute('PRAGMA index_info(%s)' % self.connection.ops.quote_name(index))
        for index_rank, column_rank, column in handle.fetchall():
            if index not in constraints:
                constraints[index] = {'columns': [], 'primary_key': False, 'unique': bool(unique), 'foreign_key': None, 'check': False, 'index': True}
            constraints[index]['columns'].append(column)
        if constraints[index]['index']:
            constraints[index]['type'] = Index.suffix
            orders = self._get_index_columns_orders(sql)
            if orders is not None:
                constraints[index]['orders'] = orders
    pk_columns = self.get_primary_key_columns(handle, table_name)
    if pk_columns:
        constraints['__primary__'] = {'columns': pk_columns, 'primary_key': True, 'unique': False, 'foreign_key': None, 'check': False, 'index': False}
    relations = enumerate(self.get_relations(handle, table_name).items())
    constraints.update({f'fk_{index}': {'columns': [column_name], 'primary_key': False, 'unique': False, 'foreign_key': (ref_table_name, ref_column_name), 'check': False, 'index': False} for index, (column_name, (ref_column_name, ref_table_name, _)) in relations})
    return constraints

@property
