def conditional_expression_supported_in_where_clause(self, expression):
    """
        Return True, if the conditional expression is directly supported in the
        WHERE clause.
        """
    if self.connection.features.has_native_boolean_field:
        return True
    if isinstance(expression, (Exists, Lookup, WhereNode)):
        return True
    if isinstance(expression, ExpressionWrapper) and expression.conditional:
        return self.conditional_expression_supported_in_where_clause(expression.expression)
    if isinstance(expression, RawSQL) and expression.conditional:
        return True
    return False

def normalize(pattern):
    """
    Given a reg-exp pattern, normalize it to an iterable of forms that
    suffice for reverse matching. This does the following:

    (1) For any repeating sections, keeps the minimum number of occurrences
        permitted (this means zero for optional groups).
    (2) If an optional group includes parameters, include one occurrence of
        that group (along with the zero occurrence case from step (1)).
    (3) Select the first (essentially an arbitrary) element from any character
        class. Select an arbitrary character for any unordered class (e.g. '.'
        or '\\w') in the pattern.
    (4) Ignore look-ahead and look-behind assertions.
    (5) Raise an error on any disjunctive ('|') constructs.

    Django's URLs for forward resolving are either all positional arguments or
    all keyword arguments. That is assumed here, as well. Although reverse
    resolving can be done using positional args when keyword args are
    specified, the two cannot be mixed in the same reverse() call.
    """
    result = []
    non_capturing_groups = []
    consume_next = True
    pattern_iter = next_char(iter(pattern))
    num_args = 0
    try:
        ch, escaped = next(pattern_iter)
    except StopIteration:
        return [('', [])]
    try:
        while True:
            if escaped:
                result.append(ch)
            elif ch == '.':
                result.append('.')
            elif ch == '|':
                raise NotImplementedError('Awaiting Implementation')
            elif ch == '^':
                pass
            elif ch == '$':
                break
            elif ch == ')':
                start = non_capturing_groups.pop()
                inner = NonCapture(result[start:])
                result = result[:start] + [inner]
            elif ch == '[':
                ch, escaped = next(pattern_iter)
                result.append(ch)
                ch, escaped = next(pattern_iter)
                while escaped or ch != ']':
                    ch, escaped = next(pattern_iter)
            elif ch == '(':
                ch, escaped = next(pattern_iter)
                if ch != '?' or escaped:
                    name = '_%d' % num_args
                    num_args += 1
                    result.append(Group(('%%(%s)s' % name, name)))
                    walk_to_end(ch, pattern_iter)
                else:
                    ch, escaped = next(pattern_iter)
                    if ch in '!=<':
                        walk_to_end(ch, pattern_iter)
                    elif ch == ':':
                        non_capturing_groups.append(len(result))
                    elif ch != 'P':
                        raise ValueError("Non-reversible reg-exp portion: '(?%s'" % ch)
                    else:
                        ch, escaped = next(pattern_iter)
                        if ch not in ('<', '='):
                            raise ValueError("Non-reversible reg-exp portion: '(?P%s'" % ch)
                        if ch == '<':
                            terminal_char = '>'
                        else:
                            terminal_char = ')'
                        name = []
                        ch, escaped = next(pattern_iter)
                        while ch != terminal_char:
                            name.append(ch)
                            ch, escaped = next(pattern_iter)
                        param = ''.join(name)
                        if terminal_char != ')':
                            result.append(Group(('%%(%s)s' % param, param)))
                            walk_to_end(ch, pattern_iter)
                        else:
                            result.append(Group(('%%(%s)s' % param, None)))
            elif ch in '*?+{':
                count, ch = get_quantifier(ch, pattern_iter)
                if ch:
                    consume_next = False
                if count == 0:
                    if contains(result[-1], Group):
                        result[-1] = Choice([None, result[-1]])
                    else:
                        result.pop()
                elif count > 1:
                    result.extend([result[-1]] * (count - 1))
            else:
                result.append(ch)
            if consume_next:
                ch, escaped = next(pattern_iter)
            consume_next = True
    except StopIteration:
        pass
    except NotImplementedError:
        return [('', [])]
    return list(zip(*flatten_result(result)))

@property
def ordered(self):
    """
        Return True if the QuerySet is ordered -- i.e. has an order_by()
        clause or a default ordering on the model (or is empty).
        """
    if isinstance(self, EmptyQuerySet):
        return True
    if self.query.extra_order_by or self.query.order_by:
        return True
    elif self.query.default_ordering and self.query.get_meta().ordering and (not self.query.group_by):
        return True
    else:
        return False

@register.simple_tag(name='querystring', takes_context=True)
def querystring(context, *args, **kwargs):
    """
    Build a query string using `args` and `kwargs` arguments.

    This tag constructs a new query string by adding, removing, or modifying
    parameters from the given positional and keyword arguments. Positional
    arguments must be mappings (such as `QueryDict` or `dict`), and
    `request.GET` is used as the starting point if `args` is empty.

    Keyword arguments are treated as an extra, final mapping. These mappings
    are processed sequentially, with later arguments taking precedence.

    Passing `None` as a value removes the corresponding key from the result.
    For iterable values, `None` entries are ignored, but if all values are
    `None`, the key is removed.

    A query string prefixed with `?` is returned.

    Raise TemplateSyntaxError if a positional argument is not a mapping or if
    keys are not strings.

    For example::

        {# Set a parameter on top of `request.GET` #}
        {% querystring foo=3 %}

        {# Remove a key from `request.GET` #}
        {% querystring foo=None %}

        {# Use with pagination #}
        {% querystring page=page_obj.next_page_number %}

        {# Use a custom ``QueryDict`` #}
        {% querystring my_query_dict foo=3 %}

        {# Use multiple positional and keyword arguments #}
        {% querystring my_query_dict my_dict foo=3 bar=None %}
    """
    if not args:
        args = [context.request.GET]
    params = QueryDict(mutable=True)
    for d in [*args, kwargs]:
        if not isinstance(d, Mapping):
            raise TemplateSyntaxError('querystring requires mappings for positional arguments (got %r instead).' % d)
        items = d.lists() if isinstance(d, QueryDict) else d.items()
        for key, value in items:
            if not isinstance(key, str):
                raise TemplateSyntaxError('querystring requires strings for mapping keys (got %r instead).' % key)
            if value is None:
                params.pop(key, None)
            elif isinstance(value, Iterable) and (not isinstance(value, str)):
                params.setlist(key, [v for v in value if v is not None])
            else:
                params[key] = value
    query_string = params.urlencode() if params else ''
    return f'?{query_string}'

def __reduce__(self):
    """
        Pickling should return the model._meta.fields instance of the field,
        not a new copy of that field. So, use the app registry to load the
        model and then the field back.
        """
    if not hasattr(self, 'model'):
        state = self.__dict__.copy()
        state.pop('_get_default', None)
        return (_empty, (self.__class__,), state)
    return (_load_field, (self.model._meta.app_label, self.model._meta.object_name, self.name))

def build_absolute_uri(self, location=None):
    """
        Build an absolute URI from the location and the variables available in
        this request. If no ``location`` is specified, build the absolute URI
        using request.get_full_path(). If the location is absolute, convert it
        to an RFC 3987 compliant URI and return it. If location is relative or
        is scheme-relative (i.e., ``//example.com/``), urljoin() it to a base
        URL constructed from the request variables.
        """
    if location is None:
        location = '//%s' % self.get_full_path()
    else:
        location = str(location)
    bits = urlsplit(location)
    if not (bits.scheme and bits.netloc):
        if bits.path.startswith('/') and (not bits.scheme) and (not bits.netloc) and ('/./' not in bits.path) and ('/../' not in bits.path):
            location = self._current_scheme_host + location.removeprefix('//')
        else:
            location = urljoin(self._current_scheme_host + self.path, location)
    return iri_to_uri(location)

@property
def _num_plurals(self):
