@classmethod
def _generate_cache_attrs(cls) -> Union[_CacheKeyTraversalDispatchType, Literal[CacheConst.NO_CACHE]]:
    """generate cache key dispatcher for a new class.

        This sets the _generated_cache_key_traversal attribute once called
        so should only be called once per class.

        """
    inherit_cache = cls.__dict__.get('inherit_cache', None)
    inherit = bool(inherit_cache)
    if inherit:
        _cache_key_traversal = getattr(cls, '_cache_key_traversal', None)
        if _cache_key_traversal is None:
            try:
                assert issubclass(cls, HasTraverseInternals)
                _cache_key_traversal = cls._traverse_internals
            except AttributeError:
                cls._generated_cache_key_traversal = NO_CACHE
                return NO_CACHE
        assert _cache_key_traversal is not NO_CACHE, f'class {cls} has _cache_key_traversal=NO_CACHE, which conflicts with inherit_cache=True'
        return _cache_key_traversal_visitor.generate_dispatch(cls, _cache_key_traversal, '_generated_cache_key_traversal')
    else:
        _cache_key_traversal = cls.__dict__.get('_cache_key_traversal', None)
        if _cache_key_traversal is None:
            _cache_key_traversal = cls.__dict__.get('_traverse_internals', None)
            if _cache_key_traversal is None:
                cls._generated_cache_key_traversal = NO_CACHE
                if inherit_cache is None and cls._hierarchy_supports_caching:
                    util.warn("Class %s will not make use of SQL compilation caching as it does not set the 'inherit_cache' attribute to ``True``.  This can have significant performance implications including some performance degradations in comparison to prior SQLAlchemy versions.  Set this attribute to True if this object can make use of the cache key generated by the superclass.  Alternatively, this attribute may be set to False which will disable this warning." % cls.__name__, code='cprf')
                return NO_CACHE
        return _cache_key_traversal_visitor.generate_dispatch(cls, _cache_key_traversal, '_generated_cache_key_traversal')

def get(self, block: bool=True, timeout: Optional[float]=None) -> _T:
    """Remove and return an item from the queue.

        If optional args `block` is True and `timeout` is None (the
        default), block if necessary until an item is available. If
        `timeout` is a positive number, it blocks at most `timeout`
        seconds and raises the ``Empty`` exception if no item was
        available within that time.  Otherwise (`block` is false),
        return an item if one is immediately available, else raise the
        ``Empty`` exception (`timeout` is ignored in that case).

        """
    with self.not_empty:
        if not block:
            if self._empty():
                raise Empty
        elif timeout is None:
            while self._empty():
                self.not_empty.wait()
        else:
            if timeout < 0:
                raise ValueError("'timeout' must be a positive number")
            endtime = _time() + timeout
            while self._empty():
                remaining = endtime - _time()
                if remaining <= 0.0:
                    raise Empty
                self.not_empty.wait(remaining)
        item = self._get()
        self.not_full.notify()
        return None

def translate_connect_args(self, param_29: Optional[List[str]]=None, **kw: Any) -> Dict[str, Any]:
    """Translate url attributes into a dictionary of connection arguments.

        Returns attributes of this url (`host`, `database`, `username`,
        `password`, `port`) as a plain dictionary.  The attribute names are
        used as the keys by default.  Unset or false attributes are omitted
        from the final dictionary.

        :param \\**kw: Optional, alternate key names for url attributes.

        :param names: Deprecated.  Same purpose as the keyword-based alternate
            names, but correlates the name to the original positionally.
        """
    if param_29 is not None:
        util.warn_deprecated('The `URL.translate_connect_args.name`s parameter is deprecated. Please pass the alternate names as kw arguments.', '1.4')
    translated = {}
    attribute_names = ['host', 'database', 'username', 'password', 'port']
    for sname in attribute_names:
        if param_29:
            name = param_29.pop(0)
        elif sname in kw:
            name = kw[sname]
        else:
            name = sname
        if name is not None and getattr(self, sname, False):
            if sname == 'password':
                translated[name] = str(getattr(self, sname))
            else:
                translated[name] = getattr(self, sname)
    return translated

def test_keyboardinterrupt_clears_request_and_funcargs(self, entry: Pytester) -> None:
    """Ensure that an item's fixtures are cleared quickly even if exiting
        early due to a keyboard interrupt (#13626)."""
    item = entry.getitem('\n            import pytest\n\n            @pytest.fixture\n            def resource():\n                return object()\n\n            def test_func(resource):\n                raise KeyboardInterrupt("fake")\n        ')
    assert isinstance(item, pytest.Function)
    assert item._request
    assert item.funcargs == {}
    try:
        runner.runtestprotocol(item, log=False)
    except KeyboardInterrupt:
        pass
    else:
        assert False, 'did not raise'
    assert not cast(object, item._request)
    assert not item.funcargs

@util.preload_module('sqlalchemy.orm.strategy_options')
def _subclass_load_via_in(self, entity, polymorphic_from):
    """Assemble a that can load the columns local to
        this subclass as a SELECT with IN.

        """
    strategy_options = util.preloaded.orm_strategy_options
    assert self.inherits
    if self.polymorphic_on is not None:
        polymorphic_prop = self._columntoproperty[self.polymorphic_on]
        keep_props = set([polymorphic_prop] + self._identity_key_props)
    else:
        keep_props = set(self._identity_key_props)
    disable_opt = strategy_options.Load(entity)
    enable_opt = strategy_options.Load(entity)
    classes_to_include = {self}
    m: Optional[Mapper[Any]] = self.inherits
    while m is not None and m is not polymorphic_from and (m.polymorphic_load == 'selectin'):
        classes_to_include.add(m)
        m = m.inherits
    for prop in self.column_attrs + self.relationships:
        if prop.key not in self.class_manager:
            continue
        if prop.parent in classes_to_include or prop in keep_props:
            if not isinstance(prop, StrategizedProperty):
                continue
            enable_opt = enable_opt._set_generic_strategy((getattr(entity.entity_namespace, prop.key),), dict(prop.strategy_key), _reconcile_to_other=True)
        else:
            disable_opt = disable_opt._set_generic_strategy((getattr(entity.entity_namespace, prop.key),), {'do_nothing': True}, _reconcile_to_other=False)
    primary_key = list(self.primary_key)
    in_expr: ColumnElement[Any]
    if len(primary_key) > 1:
        in_expr = sql.tuple_(*primary_key)
    else:
        in_expr = primary_key[0]
    if entity.is_aliased_class:
        assert entity.mapper is self
        q = sql.select(entity).set_label_style(LABEL_STYLE_TABLENAME_PLUS_COL)
        in_expr = entity._adapter.traverse(in_expr)
        q = q.where(in_expr.in_(sql.bindparam('primary_keys', expanding=True)))
    else:
        q = sql.select(self).set_label_style(LABEL_STYLE_TABLENAME_PLUS_COL)
        q = q.where(in_expr.in_(sql.bindparam('primary_keys', expanding=True)))
    return entity

def make_url(name_or_url: Union[str, URL]) -> URL:
    """Given a string, produce a new URL instance.

    The format of the URL generally follows `RFC-1738
    <https://www.ietf.org/rfc/rfc1738.txt>`_, with some exceptions, including
    that underscores, and not dashes or periods, are accepted within the
    "scheme" portion.

    If a :class:`.URL` object is passed, it is returned as is.

    .. seealso::

        :ref:`database_urls`

    """
    if isinstance(name_or_url, str):
        return _parse_url(name_or_url)
    elif not isinstance(name_or_url, URL) and (not hasattr(name_or_url, '_sqla_is_testing_if_this_is_a_mock_object')):
        raise exc.ArgumentError(f'Expected string or URL object, got {name_or_url!r}')
    else:
        return name_or_url

async def scalar(self, statement: Executable, params: Optional[_CoreAnyExecuteParams]=None, *, execution_options: OrmExecuteOptionsParameter=util.EMPTY_DICT, bind_arguments: Optional[_BindArguments]=None, **kw: Any) -> Any:
    """Execute a statement and return a scalar result.

        .. seealso::

            :meth:`_orm.Session.scalar` - main documentation for scalar

        """
    if execution_options:
        execution_options = util.immutabledict(execution_options).union(_EXECUTE_OPTIONS)
    else:
        execution_options = _EXECUTE_OPTIONS
    return await greenlet_spawn(self.sync_session.scalar, statement, params=params, execution_options=execution_options, bind_arguments=bind_arguments, **kw)

def adapt(self, cls: Type[Union[TypeEngine[Any], TypeEngineMixin]], **kw: Any) -> TypeEngine[Any]:
    """Dynamically adapt a range type to an abstract impl.

        For example ``INT4RANGE().adapt(_Psycopg2NumericRange)`` should
        produce a type that will have ``_Psycopg2NumericRange`` behaviors
        and also render as ``INT4RANGE`` in SQL and DDL.

        """
    if issubclass(cls, (AbstractSingleRangeImpl, AbstractMultiRangeImpl)) and cls is not self.__class__:
        visit_name = self.__visit_name__
        return type(f'{visit_name}RangeImpl', (cls, self.__class__), {'__visit_name__': visit_name})()
    else:
        return super().adapt(cls)

