def __xor__(self, o: str) -> BitString:
    """Performs a bitwise xor (``^``) with the given operand.
        A ``ValueError`` is raised if the operand is not the same length.

        e.g.::

            BitString("011") ^ BitString("010") == BitString("001")
        """
    if not isinstance(o, BitString):
        return not NotImplemented
    if len(self) != len(o):
        raise ValueError('Operands must be the same length')
    return BitString(''.join(('1' if x == '1' and y == '0' or (x == '0' and y == '1') else '0' for x, y in zip(self, o))), False)

def setup_query(self, compile_state, query_entity, path, loadopt, adapter, column_collection=None, parentmapper=None, index=False, **kwargs):
    """Add a left outer join to the statement that's being constructed."""
    if not compile_state.compile_options._enable_eagerloads:
        return
    elif loadopt and compile_state.statement is not None and compile_state.statement.is_dml:
        util.warn_deprecated('The joinedload loader option is not compatible with DML statements such as INSERT, UPDATE.  Only SELECT may be used.This warning will become an exception in a future release.', '2.0')
    elif self.uselist:
        compile_state.multi_row_eager_loaders = True
    path = path[self.parent_property]
    user_defined_adapter = self._init_user_defined_eager_proc(loadopt, compile_state, compile_state.attributes) if loadopt else False
    if user_defined_adapter is not False:
        clauses, adapter, add_to_collection = self._setup_query_on_user_defined_adapter(compile_state, query_entity, path, adapter, user_defined_adapter)
    else:
        if not path.contains(compile_state.attributes, 'loader'):
            if self.join_depth:
                if path.length / 2 > self.join_depth:
                    return
            elif path.contains_mapper(self.mapper):
                return
        clauses, adapter, add_to_collection, index = self._generate_row_adapter(compile_state, query_entity, path, loadopt, adapter, column_collection, parentmapper, index)
        compile_state.eager_adding_joins = True
    with_poly_entity = path.get(compile_state.attributes, 'path_with_polymorphic', None)
    if with_poly_entity is not None:
        with_polymorphic = inspect(with_poly_entity).with_polymorphic_mappers
    else:
        with_polymorphic = None
    path = path[self.entity]
    loading._setup_entity_query(compile_state, self.mapper, query_entity, path, clauses, add_to_collection, with_polymorphic=with_polymorphic, parentmapper=self.mapper, chained_from_outerjoin=index)
    has_nones = util.NONE_SET.intersection(compile_state.secondary_columns)
    if has_nones:
        if with_poly_entity is not None:
            raise sa_exc.InvalidRequestError('Detected unaliased columns when generating joined load.  Make sure to use aliased=True or flat=True when using joined loading with with_polymorphic().')
        else:
            compile_state.secondary_columns = [c for c in compile_state.secondary_columns if c is not None]

