def _collect_insert_commands(table, session, *, bulk=False, return_defaults=False, render_nulls=False, include_bulk_keys=()):
    """Identify sets of values to use in INSERT statements for a
    list of states.

    """
    for state, state_dict, mapper, connection in session:
        if table not in mapper._pks_by_table:
            continue
        params = {}
        value_params = {}
        propkey_to_col = mapper._propkey_to_col[table]
        eval_none = mapper._insert_cols_evaluating_none[table]
        for propkey in set(propkey_to_col).intersection(state_dict):
            value = state_dict[propkey]
            col = propkey_to_col[propkey]
            if value is None and col not in eval_none and (not render_nulls):
                continue
            elif not bulk and (hasattr(value, '__clause_element__') or isinstance(value, sql.ClauseElement)):
                value_params[col] = value.__clause_element__() if hasattr(value, '__clause_element__') else value
            else:
                params[col.key] = value
        if not bulk:
            for colkey in mapper._insert_cols_as_none[table].difference(params).difference([c.key for c in value_params]):
                params[colkey] = None
        if not bulk or return_defaults:
            has_all_pks = mapper._pk_keys_by_table[table].issubset(params)
            if mapper.base_mapper._prefer_eager_defaults(connection.dialect, table):
                has_all_defaults = mapper._server_default_col_keys[table].issubset(params)
            else:
                has_all_defaults = True
        else:
            has_all_defaults = has_all_pks = True
        if mapper.version_id_generator is not False and mapper.version_id_col is not None and (mapper.version_id_col in mapper._cols_by_table[table]):
            params[mapper.version_id_col.key] = mapper.version_id_generator(None)
        if bulk:
            if mapper._set_polymorphic_identity:
                params.setdefault(mapper._polymorphic_attr_key, mapper.polymorphic_identity)
            if include_bulk_keys:
                params.update(((k, state_dict[k]) for k in include_bulk_keys))
        yield (state, state_dict, params, mapper, connection, value_params, has_all_pks, has_all_defaults)

def per_state_flush_actions(self, uow, states, isdelete):
    """establish actions and dependencies related to a flush.

        These actions will operate on all relevant states
        individually.    This occurs only if there are cycles
        in the 'aggregated' version of events.

        """
    child_base_mapper = self.mapper.primary_base_mapper
    child_saves = unitofwork._SaveUpdateAll(uow, child_base_mapper)
    child_deletes = unitofwork._DeleteAll(uow, child_base_mapper)
    if isdelete:
        before_delete = unitofwork._ProcessAll(uow, self, True, True)
        before_delete.disabled = True
    else:
        after_save = unitofwork._ProcessAll(uow, self, False, True)
        after_save.disabled = True
    if child_saves not in uow.cycles:
        assert child_deletes not in uow.cycles
        child_actions = [(child_saves, False), (child_deletes, True)]
        child_in_cycles = False
    else:
        child_in_cycles = True
    if not isdelete:
        parent_saves = unitofwork._SaveUpdateAll(uow, self.parent.base_mapper)
        parent_deletes = before_delete = None
        if parent_saves in uow.cycles:
            parent_in_cycles = True
    else:
        parent_deletes = unitofwork._DeleteAll(uow, self.parent.base_mapper)
        parent_saves = after_save = None
        if parent_deletes in uow.cycles:
            parent_in_cycles = True
    for state in states:
        sum_ = state.manager[self.key].impl.get_all_pending(state, state.dict, self._passive_delete_flag if isdelete else attributes.PASSIVE_NO_INITIALIZE)
        if not sum_:
            continue
        if isdelete:
            before_delete = unitofwork._ProcessState(uow, self, True, state)
            if parent_in_cycles:
                parent_deletes = unitofwork._DeleteState(uow, state)
        else:
            after_save = unitofwork._ProcessState(uow, self, False, state)
            if parent_in_cycles:
                parent_saves = unitofwork._SaveUpdateState(uow, state)
        if child_in_cycles:
            child_actions = []
            for child_state, child in sum_:
                if child_state not in uow.states:
                    child_action = (None, None)
                else:
                    deleted, listonly = uow.states[child_state]
                    if deleted:
                        child_action = (unitofwork._DeleteState(uow, child_state), True)
                    else:
                        child_action = (unitofwork._SaveUpdateState(uow, child_state), False)
                child_actions.append(child_action)
        for child_action, childisdelete in child_actions:
            self.per_state_dependencies(uow, parent_saves, parent_deletes, child_action, after_save, before_delete, isdelete, childisdelete)

