def _get_crud_params(record: SQLCompiler, stmt: ValuesBase, compile_state: DMLState, toplevel: bool, **kw: Any) -> _CrudParams:
    """create a set of tuples representing column/string pairs for use
    in an INSERT or UPDATE statement.

    Also generates the Compiled object's postfetch, prefetch, and
    returning column collections, used for default handling and ultimately
    populating the CursorResult's prefetch_cols() and postfetch_cols()
    collections.

    """
    record.postfetch = []
    record.insert_prefetch = []
    record.update_prefetch = []
    record.implicit_returning = []
    visiting_cte = kw.get('visiting_cte', None)
    if visiting_cte is not None:
        kw.pop('accumulate_bind_names', None)
    assert 'accumulate_bind_names' not in kw, "Don't know how to handle insert within insert without a CTE"
    bindmarkers: MutableMapping[ColumnElement[Any], DMLTargetCopy[Any]] = {}
    kw['bindmarkers'] = bindmarkers
    _column_as_key, _getattr_col_key, _col_bind_name = _key_getters_for_crud_column(record, stmt, compile_state)
    record._get_bind_name_for_col = _col_bind_name
    if stmt._returning and stmt._return_defaults:
        raise exc.CompileError("Can't compile statement that includes returning() and return_defaults() simultaneously")
    if compile_state.isdelete:
        _setup_delete_return_defaults(record, stmt, compile_state, (), _getattr_col_key, _column_as_key, _col_bind_name, (), (), toplevel, kw)
        return _CrudParams([], [])
    if record.column_keys is None and compile_state._no_parameters:
        return _CrudParams([(c, record.preparer.format_column(c), _create_bind_param(record, c, None, required=True), (c.key,)) for c in stmt.table.columns if not c._omit_from_statements], [])
    stmt_parameter_tuples: Optional[List[Tuple[Union[str, ColumnClause[Any]], Any]]]
    spd: Optional[MutableMapping[_DMLColumnElement, Any]]
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        mp = compile_state._multi_parameters
        assert mp is not None
        spd = mp[0]
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    elif compile_state._dict_parameters:
        spd = compile_state._dict_parameters
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    else:
        stmt_parameter_tuples = spd_str_key = None
    if record.column_keys is None:
        parameters = {}
    elif stmt_parameter_tuples:
        assert spd_str_key is not None
        parameters = {_column_as_key(key): REQUIRED for key in record.column_keys if key not in spd_str_key}
    else:
        parameters = {_column_as_key(key): REQUIRED for key in record.column_keys}
    values: List[_CrudParamElementStr] = []
    if stmt_parameter_tuples is not None:
        _get_stmt_parameter_tuples_params(record, compile_state, parameters, stmt_parameter_tuples, _column_as_key, values, kw)
    check_columns: Dict[str, ColumnClause[Any]] = {}
    if dml.isupdate(compile_state) and compile_state.is_multitable:
        _get_update_multitable_params(record, stmt, compile_state, stmt_parameter_tuples, check_columns, _col_bind_name, _getattr_col_key, values, kw)
    if _compile_state_isinsert(compile_state) and stmt._select_names:
        assert not compile_state._has_multi_parameters
        _scan_insert_from_select_cols(record, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
        use_insertmanyvalues = False
        use_sentinel_columns = None
    else:
        use_insertmanyvalues, use_sentinel_columns = _scan_cols(record, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
    if parameters and stmt_parameter_tuples:
        check = set(parameters).intersection((_column_as_key(k) for k, v in stmt_parameter_tuples)).difference(check_columns)
        if check:
            if dml.isupdate(compile_state):
                tables_mentioned = set((c.table for c, v in stmt_parameter_tuples if isinstance(c, ColumnClause) and c.table is not None)).difference([compile_state.dml_table])
                multi_not_in_from = tables_mentioned.difference(compile_state._extra_froms)
                if tables_mentioned and (not compile_state.is_multitable or not record.render_table_with_column_in_update_from):
                    if not record.render_table_with_column_in_update_from:
                        preamble = 'Backend does not support additional tables in the SET clause'
                    else:
                        preamble = 'Statement is not a multi-table UPDATE statement'
                    raise exc.CompileError(f"""{preamble}; cannot include columns from table(s) {', '.join((f"'{t.description}'" for t in tables_mentioned))} in SET clause""")
                elif multi_not_in_from:
                    assert record.render_table_with_column_in_update_from
                    raise exc.CompileError(f"""Multi-table UPDATE statement does not include table(s) {', '.join((f"'{t.description}'" for t in multi_not_in_from))}""")
            raise exc.CompileError('Unconsumed column names: %s' % ', '.join(('%s' % (c,) for c in check)))
    is_default_metavalue_only = False
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        assert not stmt._select_names
        multi_extended_values = _extend_values_for_multiparams(record, stmt, compile_state, cast('Sequence[_CrudParamElementStr]', values), cast('Callable[..., str]', _column_as_key), kw)
        if bindmarkers:
            _replace_bindmarkers(record, _column_as_key, bindmarkers, compile_state, values, kw)
            for m_v in multi_extended_values:
                _replace_bindmarkers(record, _column_as_key, bindmarkers, compile_state, m_v, kw)
        return _CrudParams(values, multi_extended_values)
    elif not values and record.for_executemany and record.dialect.supports_default_metavalue:
        values = [(_as_dml_column(stmt.table.columns[0]), record.preparer.format_column(stmt.table.columns[0]), record.dialect.default_metavalue_token, ())]
        is_default_metavalue_only = True
    if bindmarkers:
        _replace_bindmarkers(record, _column_as_key, bindmarkers, compile_state, values, kw)
    return _CrudParams(values, [], is_default_metavalue_only=is_default_metavalue_only, use_insertmanyvalues=use_insertmanyvalues, use_sentinel_columns=use_sentinel_columns)

def do_connect(self, dialect: Dialect, conn_rec: ConnectionPoolEntry, entry: Tuple[Any, ...], cparams: Dict[str, Any]) -> Optional[DBAPIConnection]:
    """Receive connection arguments before a connection is made.

        This event is useful in that it allows the handler to manipulate the
        cargs and/or cparams collections that control how the DBAPI
        ``connect()`` function will be called. ``cargs`` will always be a
        Python list that can be mutated in-place, and ``cparams`` a Python
        dictionary that may also be mutated::

            e = create_engine("postgresql+psycopg2://user@host/dbname")


            @event.listens_for(e, "do_connect")
            def receive_do_connect(dialect, conn_rec, cargs, cparams):
                cparams["password"] = "some_password"

        The event hook may also be used to override the call to ``connect()``
        entirely, by returning a non-``None`` DBAPI connection object::

            e = create_engine("postgresql+psycopg2://user@host/dbname")


            @event.listens_for(e, "do_connect")
            def receive_do_connect(dialect, conn_rec, cargs, cparams):
                return psycopg2.connect(*cargs, **cparams)

        .. seealso::

            :ref:`custom_dbapi_args`

        """

def last_updated_params(self) -> Union[List[_MutableCoreSingleExecuteParams], _MutableCoreSingleExecuteParams]:
    """Return the collection of updated parameters from this
        execution.

        Raises :class:`~sqlalchemy.exc.InvalidRequestError` if the executed
        statement is not a compiled expression construct
        or is not an update() construct.

        """
    if not self.context.compiled:
        raise exc.InvalidRequestError('Statement is not a compiled expression construct.')
    elif not self.context.isupdate:
        raise exc.InvalidRequestError('Statement is not an update() expression construct.')
    elif self.context.executemany:
        return self.context.compiled_parameters
    else:
        return self.context.compiled_parameters[0]

def scalar(self, statement: Executable, parameters: Optional[_CoreSingleExecuteParams]=None, *, execution_options: Optional[CoreExecuteOptionsParameter]=None) -> Any:
    """Executes a SQL statement construct and returns a scalar object.

        This method is shorthand for invoking the
        :meth:`_engine.Result.scalar` method after invoking the
        :meth:`_engine.Connection.execute` method.  Parameters are equivalent.

        :return: a scalar Python value representing the first column of the
         first row returned.

        """
    distilled_parameters = _distill_params_20(parameters)
    try:
        meth = statement._execute_on_scalar
    except AttributeError as err:
        raise exc.ObjectNotExecutableError(statement) from err
    else:
        return meth(self, distilled_parameters, execution_options or NO_OPTIONS)

