@classmethod
@util.preload_module('sqlalchemy.orm.util')
def identity_key(cls, class_: Optional[Type[Any]]=None, ident: Union[Any, Tuple[Any, ...]]=None, *, instance: Optional[Any]=None, row: Optional[Union[Row[Unpack[TupleAny]], RowMapping]]=None, identity_token: Optional[Any]=None) -> _IdentityKeyType[Any]:
    """Return an identity key.

        This is an alias of :func:`.util.identity_key`.

        """
    return util.preloaded.orm_util.identity_key(class_, ident, instance=instance, row=row, identity_token=identity_token)

def get_from_identity(session: Session, index: Mapper[_O], key: _IdentityKeyType[_O], passive: PassiveFlag) -> Union[LoaderCallableStatus, Optional[_O]]:
    """Look up the given key in the given session's identity map,
    check the object for expired state if found.

    """
    instance = session.identity_map.get(key)
    if instance is not None:
        state = attributes.instance_state(instance)
        if index.inherits and (not state.mapper.isa(index)):
            return attributes.PASSIVE_CLASS_MISMATCH
        if state.expired:
            if not passive & attributes.SQL_OK:
                return attributes.PASSIVE_NO_RESULT
            elif not passive & attributes.RELATED_OBJECT_OK:
                return instance
            try:
                state._load_expired(state, passive)
            except orm_exc.ObjectDeletedError:
                session._remove_newly_deleted([state])
                return None
        return instance
    else:
        return None

def get_lines_after(self, fnline: str) -> Sequence[str]:
    """Return all lines following the given line in the text.

        The given line can contain glob wildcards.
        """
    for i, line in enumerate(self.lines):
        if fnline == line or fnmatch(line, fnline):
            return self.lines[i + 1:]
    raise ValueError(f'line {fnline!r} not found in output')

@util.preload_module('sqlalchemy.sql.dml')
def delete(self) -> Delete:
    """Generate a :func:`_expression.delete` construct against this
        :class:`_expression.TableClause`.

        E.g.::

            table.delete().where(table.c.id == 7)

        See :func:`_expression.delete` for argument and usage information.

        """
    return util.preloaded.sql_dml.Delete(self)

@property
def unmodified(self) -> Set[str]:
    """Return the set of keys which have no uncommitted changes"""
    return set(self.manager).difference(self.committed_state)

@property
def date_historic(self):
    """target dialect supports representation of Python
        datetime.datetime() objects with historic (pre 1970) values."""
    return exclusions.closed()

@reflection.cache
def has_sequence(self, connection, item, schema=None, dblink=None, **kw):
    """Supported kw arguments are: ``dblink`` to reflect via a db link."""
    if not schema:
        schema = self.default_schema_name
    query = select(dictionary.all_sequences.c.sequence_name).where(dictionary.all_sequences.c.sequence_name == self.denormalize_schema_name(item), dictionary.all_sequences.c.sequence_owner == self.denormalize_schema_name(schema))
    cursor = self._execute_reflection(connection, query, dblink, returns_long=False)
    return bool(cursor.scalar())

