def pytest_generate_tests(self, metafunc: Metafunc) -> None:
    """Generate new tests based on parametrized fixtures used by the given metafunc"""

    def get_parametrize_mark_argnames(mark: Mark) -> Sequence[str]:
        args, _ = ParameterSet._parse_parametrize_args(*mark.args, **mark.kwargs)
        return args
    for argname in metafunc.fixturenames:
        fixture_defs = metafunc._arg2fixturedefs.get(argname, ())
        if any((argname in get_parametrize_mark_argnames(mark) for mark in metafunc.definition.iter_markers('parametrize'))):
            continue
        for fixturedef in reversed(fixture_defs):
            if fixturedef.params is not None:
                metafunc.parametrize(argname, fixturedef.params, indirect=True, scope=fixturedef.scope, ids=fixturedef.ids)
                break
            if argname not in fixturedef.argnames:
                break

@HasMemoized.memoized_attribute
def _tq_key_label(self) -> Optional[str]:
    """table qualified label based on column key.

        for table-bound columns this is <tablename>_<column key/proxy key>;

        all other expressions it resolves to key/proxy key.

        """
    proxy_key = self._proxy_key
    if proxy_key and proxy_key != self.name:
        return self._gen_tq_label(proxy_key)
    else:
        return self._tq_label

def append_without_event(self, item: Any) -> None:
    """Add or restore an entity to the collection, firing no events."""
    if self.empty:
        self._refuse_empty()
    self._data()._sa_appender(item, _sa_initiator=False)

def determine_setup(*, inifile: str | None, override_ini: Sequence[str] | None, args: Sequence[str], rootdir_cmd_arg: str | None, invocation_dir: Path) -> tuple[Path, Path | None, ConfigDict, Sequence[str]]:
    """Determine the rootdir, inifile and ini configuration values from the
    command line arguments.

    :param inifile:
        The `--inifile` command line argument, if given.
    :param override_ini:
        The -o/--override-ini command line arguments, if given.
    :param args:
        The free command line arguments.
    :param rootdir_cmd_arg:
        The `--rootdir` command line argument, if given.
    :param invocation_dir:
        The working directory when pytest was invoked.

    :raises UsageError:
    """
    rootdir = None
    dirs = get_dirs_from_args(args)
    ignored_config_files: Sequence[str] = []
    if inifile:
        inipath_ = absolutepath(inifile)
        inipath: Path | None = inipath_
        inicfg = load_config_dict_from_file(inipath_) or {}
        if rootdir_cmd_arg is None:
            rootdir = inipath_.parent
    else:
        ancestor = get_common_ancestor(invocation_dir, dirs)
        rootdir, inipath, inicfg, ignored_config_files = locate_config(invocation_dir, [ancestor])
        if rootdir is None and rootdir_cmd_arg is None:
            for possible_rootdir in (ancestor, *ancestor.parents):
                if (possible_rootdir / 'setup.py').is_file():
                    rootdir = possible_rootdir
                    break
            else:
                if dirs != [ancestor]:
                    rootdir, inipath, inicfg, _ = locate_config(invocation_dir, dirs)
                if rootdir is None:
                    rootdir = get_common_ancestor(invocation_dir, [invocation_dir, ancestor])
                    if is_fs_root(rootdir):
                        rootdir = ancestor
    if rootdir_cmd_arg:
        rootdir = absolutepath(os.path.expandvars(rootdir_cmd_arg))
        if not rootdir.is_dir():
            raise UsageError(f"Directory '{rootdir}' not found. Check your '--rootdir' option.")
    ini_overrides = parse_override_ini(override_ini)
    inicfg.update(ini_overrides)
    assert rootdir is not None
    return (rootdir, inipath, inicfg, ignored_config_files)

@testing.combinations('PK_test_table', 'pk_test_table', 'mixedCasePK', 'pk.with.dots', argnames='pk_name')
@testing.requires.primary_key_constraint_reflection
@testing.requires.reflects_pk_names
def test_get_pk_constraint_quoted_name(self, entry, metadata, pk_name):
    """Test that primary key constraint names with various casing are
        properly reflected."""
    Table('test_table', metadata, Column('id', Integer), Column('data', String(50)), sa.PrimaryKeyConstraint('id', name=pk_name))
    metadata.create_all(entry)
    insp = inspect(entry)
    pk_cons = insp.get_pk_constraint('test_table')
    eq_(pk_cons['name'], pk_name)
    eq_(pk_cons['constrained_columns'], ['id'])
